        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "扣除产品或服务的直接成本后，营收中剩下的比例。70% 的毛利率意味着每 100 元销售额留下 70 元用于支付其他所有开支。",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "负债权益比：总负债除以股东权益。数值越高，公司越依赖借债，收益和风险都会被放大。不同行业的正常水平差别很大。",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "净资产收益率：年度利润除以股东权益，反映公司把投入的资本转化为利润的效率。非常高的 ROE 也可能来自大量借债。",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "股价相对大盘的波动程度。1 表示与大盘同步，大于 1 波动更大，小于 1 波动更小。它描述的是过去的波动，不代表未来收益。",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "股息率：每股年度股息除以股价。2% 的股息率意味着每投资 100 元，每年大约获得 2 元股息。异常高的股息率可能说明市场预期股息会被削减。",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "公司营收相比一年前增长了多少，反映扣除成本前的业务需求。结合利润率来看，才能判断增长是否赚钱。",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "每股收益相比一年前增长了多少。持续增长通常支撑更高的估值；单独一年的高增长可能来自一次性项目。",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "市净率：股价除以每股账面价值（资产减负债）。低于 1 表示市场给公司的估值低于其账面净资产。对银行和重资产企业比对软件公司更有意义。",
