        "Market data: Yahoo Finance and Finnhub. Prices may be delayed.": "市場データ：Yahoo Finance、Finnhub。価格は遅延する場合があります。",
        "Version": "バージョン",
        "About & Data Sources": "情報とデータソース",
        "Investment style: %@": "投資スタイル：%@",
        "Question %d of %d": "質問 %d / %d",
        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "成長を目指すために大きな値動きも許容できるタイプです。Orionは成長企業や新しいトレンドについて、そのリスクも含めて解説します。",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "成長と安定のバランスを重視するタイプです。Orionは成長企業と安定した投資の両方、そしてそれらの組み合わせ方を解説します。",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "安定を最優先するタイプです。Orionの解説では、分散投資、インカム投資、資産の守り方により多くの時間を割きます。",
        "Prices often move more than usual around an earnings report.": "決算発表の前後は、株価が通常より大きく動くことがよくあります。",
        "Markets are closed for the weekend": "週末のため市場は休場です",
        "Markets have closed for the day": "本日の取引は終了しました",
        "Markets open at 9:30 AM ET": "市場は米国東部時間 9:30 AM に開きます",
        "Markets are open · close at 4:00 PM ET": "取引中 · 米国東部時間 4:00 PM に終了",
        "As of %@ ET": "米国東部時間 %@ 時点",
        "Add %@ to watchlist": "%@ をウォッチリストに追加",
        "%@ added to watchlist": "%@ をウォッチリストに追加しました",
        "Added": "追加済み",
        "Dismiss": "閉じる",
        "Adding %@…": "%@ を追加中…",
        "%@ was added here but couldn't be saved to your account.": "%@ はここに追加されましたが、アカウントに保存できませんでした。",
        "Added for this session. Sign in to keep your watchlist.": "このセッションのみ追加されました。ウォッチリストを保存するにはサインインしてください。",
        "Couldn't add %@. Check your connection and try again.": "%@ を追加できませんでした。接続を確認して、もう一度お試しください。",
        "%@ is already in your watchlist.": "%@ はすでにウォッチリストにあります。",
        "D/E": "D/E",
        "ROE": "ROE",
        "Beta": "ベータ",
        "P/B": "PBR",
        "P/E": "PER",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "営業利益率：給与、研究開発費、マーケティング費などすべての営業費用を差し引いた後に売上高に残る割合です。利息や税金を差し引く前の本業の収益力を示します。",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "製品やサービスの直接原価を差し引いた後に売上高に残る割合です。粗利益率70%の場合、売上100ドルにつき70ドルがその他すべての費用に充てられます。",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "負債資本倍率（D/Eレシオ）：総負債を株主資本で割ったものです。数値が高いほど借入への依存度が高く、利益とリスクの両方が拡大します。標準的な水準は業種によって大きく異なります。",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "自己資本利益率（ROE）：年間利益を株主資本で割ったものです。投下資本をどれだけ効率よく利益に変えているかを示します。非常に高いROEは多額の借入によるものである場合もあります。",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "市場全体と比べて、その株価がどの程度動く傾向にあったかを示します。1は市場と同程度、1を超えると値動きが大きく、1未満だと小さくなります。過去の変動性を表すもので、将来のリターンを示すものではありません。",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "配当利回り：1株あたりの年間配当を株価で割ったものです。利回り2%の場合、100ドルの投資につき年間約2ドルが支払われます。利回りが異常に高い場合、市場が減配を予想している可能性があります。",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "売上高が前年と比べてどれだけ伸びたかを示します。費用を差し引く前の事業への需要を表します。成長が利益を伴っているかは、利益率と合わせて確認してください。",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "1株あたり利益（EPS）が前年と比べてどれだけ伸びたかを示します。持続的な成長は高いバリュエーションを支える傾向がありますが、1年だけの好調は一時的な要因による場合もあります。",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "株価純資産倍率（PBR）：株価を1株あたりの純資産（資産から負債を引いたもの）で割ったものです。1未満の場合、市場は会社を会計上の純資産より低く評価していることになります。ソフトウェア企業よりも、銀行や資産の多い企業で意味を持つ指標です。",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "株価収益率（PER）：株価を直近1年間の1株あたり利益で割ったものです。投資家が利益1ドルに対して何ドル支払っているかを示します。数値が高い場合、投資家がより速い成長を期待しているか、株価が割高である可能性があります。同業他社と比較すると最も参考になります。",
        "Generate snapshot": "スナップショットを生成",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "%@ に関するAIによる簡潔なリサーチ要約です：株価の変動要因、主なリスク、注目点をまとめています。推奨ではありません。",
        "Couldn't generate the snapshot right now.": "現在スナップショットを生成できません。",
        "Explain %@ for %@ with Orion AI": "Orion AIで %2$@ の%1$@ を解説",
