        "Brokerages connect securely through SnapTrade, banks through Plaid. You sign in on your institution's own page.": "証券会社はSnapTrade、銀行はPlaidを通じて安全に接続されます。サインインは各金融機関のページで行います。",
        "Sign in to this bank again to keep it updated.": "更新を続けるには、この銀行に再度サインインしてください。",
