        "%@ hasn't updated recently": "%@ は最近更新されていません",
        "%@ couldn't be loaded": "%@ を読み込めませんでした",
        "Account connection": "口座の接続",
        "%d connections need attention": "%d 件の接続に対応が必要です",
        "Your net worth may be out of date. Tap to fix.": "純資産が最新でない可能性があります。タップして修正してください。",
        "Non-registered": "非登録口座",
        "Tax Assistant": "税務アシスタント",
        "TFSA · RRSP · FHSA room and superficial loss watch": "TFSA · RRSP · FHSA 枠と見かけ上の損失チェック",
        "%d items need attention": "%d 件の項目に注意が必要です",
        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "情報提供のみを目的としており、税務アドバイスではありません。数値はCRA My Accountまたは税務の専門家にご確認ください。",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "証券口座を連携すると、TFSA、RRSP、FHSAへの拠出額を追跡できます。",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "連携口座の中にTFSA、RRSP、FHSA口座が見つかりません。",
        "%d contribution room": "%d 年の拠出枠",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "拠出額は、連携口座における今暦年の入金から集計されます。金融機関間の移管は含まれません。年初60日以内のRRSP拠出は前の課税年度に適用できます。",
        "Set room": "枠を設定",
        "Edit room": "枠を編集",
        "Contributed this year": "今年の拠出額",
        "Room left": "残りの枠",
        "Over your room by": "枠の超過額",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "CRAは超過拠出に対して月1%%のペナルティを課します（この場合 %@）。超過分を引き出すとペナルティは止まります。",
        "Within the $2,000 RRSP over-contribution allowance.": "RRSPの超過拠出許容額 $2,000 の範囲内です。",
        "Enter your room from CRA My Account to see what's left.": "CRA My Accountで確認した拠出枠を入力すると、残りの枠が表示されます。",
        "Withdrawn this year: %@ — this room comes back on January 1.": "今年の引出額：%@。この枠は1月1日に戻ります。",
        "No recent losses to watch.": "注意が必要な最近の損失はありません。",
        "Superficial loss watch": "見かけ上の損失チェック",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "非登録口座で損失を出して売却し、その前後30日以内にあなた（または配偶者）がTFSAやRRSPを含むいずれかの口座で同じ証券を購入し、引き続き保有している場合、CRAはその損失を認めません。Orionは連携しているすべての口座を確認します。配偶者の口座は、連携していない限り対象外です。",
        "Sold at a loss on %@ in %@": "%@ に %@ で損失を出して売却",
        "Don't buy %@ in any account until %@ to keep this loss.": "この損失を維持するには、%2$@ まではどの口座でも %1$@ を購入しないでください。",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "見かけ上の損失に該当する可能性があります：30日以内に再購入し、現在も保有しています。",
        "Bought on %@ in %@": "%@ に %@ で購入",
        "Amount in CAD": "金額（カナダドル）",
        "%@ room available on January 1, %d": "%2$d 年1月1日に利用可能な %1$@ の枠",
        "Clear": "クリア",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room で確認できます。",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "最新のNotice of AssessmentまたはCRA My AccountにあるRRSP控除限度額を使用してください。",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "CRA My Accountで確認できます。FHSAの年間限度額は $8,000 に繰越額を加えたものです。",
        "AI Research Snapshot": "AIリサーチ・スナップショット",
        "Positive": "ポジティブ",
        "Mixed": "まちまち",
        "Negative": "ネガティブ",
        "What to Watch": "注目点",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "AIが生成した学習用のリサーチ要約です。売買を推奨するものではありません。",
        "Get a side-by-side comparison with an AI summary": "AI要約付きで並べて比較",
        "Example Portfolio to Explore": "学習用のサンプルポートフォリオ",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "模擬取引で試せる学習用のサンプルです。推奨ではありません。投資の前にご自身で調べてください。",
        "Ideas to Explore": "注目のテーマ",
        "Popular names in your interests · not a recommendation": "関心分野で人気の銘柄 · 推奨ではありません",
        "Help Orion tailor what it explains and shows you": "Orionの解説や表示内容をあなたに合わせて調整します",
        "Pick the categories you want to follow and learn about": "フォローして学びたいカテゴリを選んでください",
        "Update the categories you follow": "フォローするカテゴリを更新",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "AI機能はオフになっています。使用するには、その他 → AIデータ共有 でGoogle Geminiとの共有を許可してください。",
        "Before you use Orion AI": "Orion AIをご利用になる前に",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "OrionのAI機能は、第三者サービスであるGoogle Geminiを利用しています。回答のため、OrionはGoogleに以下を送信します：",
        "What you type or say to Orion, and any images or files you attach": "Orionに入力または話した内容、および添付した画像やファイル",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "質問した銘柄の公開市場データ（価格、ファンダメンタルズ、ニュースの見出し）",
        "Your language and the investing preferences you chose": "言語設定と、選択した投資の好み",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "Orionは、連携口座の残高、保有銘柄、口座番号、氏名、メールアドレスをAIに送信しません。",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AIは学習とリサーチのためのものです。登録投資顧問ではなく、何を売買すべきかを指示することはありません。",
        "You can turn this off any time in More → AI Data Sharing.": "この設定は、その他 → AIデータ共有 からいつでもオフにできます。",
        "Google processes this data under its own terms and may handle it outside Canada.": "Googleは独自の規約に基づいてこのデータを処理し、カナダ国外で処理する場合があります。",
        "Allow and continue": "許可して続行",
        "Not now": "後で",
        "AI Data Sharing": "AIデータ共有",
        "Send your AI questions to Google Gemini": "AIへの質問をGoogle Geminiに送信",
        "Disclaimer": "免責事項",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "Orion Financeは情報と教育のみを提供します。登録投資顧問、ディーラー、税務の専門家ではなく、アプリ内のいかなる内容も、証券の購入、売却、保有を推奨するものではありません。",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "AIが生成した内容は誤っていたり古かったりする場合があります。市場データは遅延する場合があります。連携口座のデータはSnapTradeとPlaidを通じて各金融機関から取得しており、公式の取引明細書と一致しない場合があります。",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "税務機能は問題に気づくための概算です。拠出枠はCRA My Accountで確認し、判断を下す前に資格のある専門家にご相談ください。",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "Orionは口座の情報を読み取るだけです。取引、資金の移動、金融機関での変更は一切できません。",
