        "Prices often move more than usual around an earnings report.": "실적 발표 전후에는 주가가 평소보다 크게 움직이는 경우가 많습니다.",
        "Markets are closed for the weekend": "주말이라 미국 증시가 휴장합니다",
        "Markets have closed for the day": "오늘 미국 증시가 마감되었습니다",
        "Markets open at 9:30 AM ET": "미국 증시는 미국 동부시간 9:30 AM에 개장합니다",
        "Markets are open · close at 4:00 PM ET": "미국 증시 거래 중 · 미국 동부시간 4:00 PM 마감",
        "As of %@ ET": "미국 동부시간 %@ 기준",
        "Add %@ to watchlist": "관심 종목에 %@ 추가",
        "%@ added to watchlist": "%@이(가) 관심 종목에 추가되었습니다",
        "Added": "추가됨",
        "Dismiss": "닫기",
        "Adding %@…": "%@ 추가 중…",
        "%@ was added here but couldn't be saved to your account.": "%@이(가) 여기에 추가되었지만 계정에 저장하지 못했습니다.",
        "Added for this session. Sign in to keep your watchlist.": "이번 세션에만 추가되었습니다. 관심 종목을 저장하려면 로그인하세요.",
        "Couldn't add %@. Check your connection and try again.": "%@을(를) 추가하지 못했습니다. 인터넷 연결을 확인한 후 다시 시도하세요.",
        "%@ is already in your watchlist.": "%@은(는) 이미 관심 종목에 있습니다.",
        "D/E": "부채비율",
        "ROE": "ROE",
        "Beta": "베타",
        "P/B": "P/B",
        "P/E": "P/E",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "영업이익률: 급여, 연구개발, 마케팅 등 모든 영업 비용을 제외하고 매출에서 남는 비율입니다. 이자와 세금 전 핵심 사업의 수익성을 보여 줍니다.",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "제품이나 서비스를 만드는 직접 비용을 제외하고 매출에서 남는 비율입니다. 매출총이익률이 70%라면 매출 $100마다 $70가 남아 나머지 모든 비용에 쓰입니다.",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "부채비율: 총부채를 자기자본으로 나눈 값입니다. 수치가 높을수록 회사가 차입에 더 의존하며, 이익과 위험이 모두 커집니다. 적정 수준은 업종마다 크게 다릅니다.",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "자기자본이익률: 연간 이익을 자기자본으로 나눈 값입니다. 회사가 투입된 자본을 얼마나 효율적으로 이익으로 바꾸는지 보여 줍니다. ROE가 매우 높다면 차입이 많아서일 수도 있습니다.",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "주가가 시장 전체에 비해 얼마나 움직여 왔는지를 나타냅니다. 1은 시장과 같이 움직이고, 1보다 크면 변동이 더 크며, 1보다 작으면 변동이 더 작습니다. 과거의 변동성을 나타낼 뿐, 미래 수익을 의미하지 않습니다.",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "배당수익률: 주당 연간 배당금을 주가로 나눈 값입니다. 배당수익률이 2%라면 $100 투자할 때마다 1년에 약 $2를 받습니다. 배당수익률이 비정상적으로 높다면 시장이 배당 삭감을 예상한다는 뜻일 수 있습니다.",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "회사의 매출이 1년 전보다 얼마나 늘었는지를 나타냅니다. 비용을 제외하기 전의 사업 수요를 보여 주므로, 이익률과 함께 보면 성장이 수익으로 이어지는지 알 수 있습니다.",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "주당순이익(EPS)이 1년 전보다 얼마나 늘었는지를 나타냅니다. 꾸준한 성장은 더 높은 밸류에이션을 뒷받침하는 경향이 있으며, 한 해만 크게 늘었다면 일회성 항목 때문일 수 있습니다.",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "주가순자산비율: 주가를 주당 장부가치(자산에서 부채를 뺀 값)로 나눈 값입니다. 1보다 낮으면 시장이 회사를 회계상 순자산보다 낮게 평가한다는 뜻입니다. 소프트웨어 기업보다 은행이나 자산이 많은 기업에서 더 의미가 있습니다.",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "주가수익비율: 주가를 최근 1년간의 주당순이익으로 나눈 값입니다. 투자자가 이익 1달러당 몇 달러를 지불하는지 보여 줍니다. 수치가 높으면 투자자가 더 빠른 성장을 기대하거나 주가가 비싸다는 뜻인 경우가 많습니다. 비슷한 기업과 비교할 때 가장 유용합니다.",
        "Generate snapshot": "스냅샷 생성",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "AI가 작성한 %@의 간단한 리서치 요약입니다: 주가를 움직이는 요인, 주요 위험, 주목할 점. 추천이 아닙니다.",
        "Couldn't generate the snapshot right now.": "지금은 스냅샷을 생성할 수 없습니다.",
        "Explain %@ for %@ with Orion AI": "Orion AI로 %2$@의 %1$@ 설명 보기",
        "Retry": "다시 시도",
        "Couldn't load an explanation right now.": "지금은 설명을 불러올 수 없습니다.",
        "Asking Orion…": "Orion에게 묻는 중…",
        "For %@": "%@ 대상",
        "Linked Accounts": "연결된 계좌",
        "Bank": "은행",
        "Disconnect this bank?": "이 은행 연결을 해제할까요?",
        "%@ accounts will be removed from Orion. Your bank account itself is not affected.": "%@ 계좌가 Orion에서 삭제됩니다. 실제 은행 계좌에는 영향이 없습니다.",
        "Connect a Bank": "은행 연결",
        "Connect Another Bank": "다른 은행 연결",
        "Brokerages connect securely through SnapTrade, banks through Plaid. You sign in on your institution's own page.": "증권사는 SnapTrade, 은행은 Plaid를 통해 안전하게 연결됩니다. 로그인은 해당 금융기관의 페이지에서 합니다.",
        "Sign in to this bank again to keep it updated.": "계속 업데이트하려면 이 은행에 다시 로그인하세요.",
        "Couldn't load this bank right now.": "지금은 이 은행 정보를 불러올 수 없습니다.",
        "Past 5 days": "지난 5일",
        "Past month": "지난 1개월",
        "Past 6 months": "지난 6개월",
        "Past year": "지난 1년",
        "Total": "합계",
        "By institution": "금융기관별",
        "Show total": "합계 보기",
        "Split by institution": "금융기관별로 나누기",
        "%@ needs you to sign in again": "%@에 다시 로그인해야 합니다",
        "%@ hasn't updated since %@": "%@이(가) %@ 이후 업데이트되지 않았습니다",
        "%@ hasn't updated recently": "%@이(가) 최근 업데이트되지 않았습니다",
        "%@ couldn't be loaded": "%@을(를) 불러올 수 없습니다",
        "Account connection": "계좌 연결",
        "%d connections need attention": "%d개의 연결을 확인해야 합니다",
        "Your net worth may be out of date. Tap to fix.": "순자산이 최신 상태가 아닐 수 있습니다. 탭하여 해결하세요.",
        "Non-registered": "비등록 계좌",
        "Tax Assistant": "세금 도우미",
        "TFSA · RRSP · FHSA room and superficial loss watch": "TFSA · RRSP · FHSA 한도 및 피상적 손실(superficial loss) 확인",
        "%d items need attention": "%d개 항목을 확인해야 합니다",
        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "정보 제공용이며 세무 조언이 아닙니다. 수치는 CRA My Account 또는 세무 전문가를 통해 확인하세요.",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "증권 계좌를 연결하면 TFSA, RRSP, FHSA 납입액을 추적할 수 있습니다.",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "연결된 계좌 중 TFSA, RRSP, FHSA 계좌가 없습니다.",
        "%d contribution room": "%d년 납입 한도",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "납입액은 연결된 계좌에서 이번 역년 기준으로 집계됩니다. 금융기관 간 이체는 포함되지 않습니다. 연초 60일 이내의 RRSP 납입액은 전년도 과세연도에 적용할 수 있습니다.",
        "Set room": "한도 설정",
        "Edit room": "한도 수정",
        "Contributed this year": "올해 납입액",
        "Room left": "남은 한도",
        "Over your room by": "한도 초과액",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "CRA는 초과 납입액에 대해 매월 1%%의 벌금을 부과합니다(현재 초과액 %@). 벌금을 멈추려면 초과분을 인출하세요.",
        "Within the $2,000 RRSP over-contribution allowance.": "RRSP 초과 납입 허용액 $2,000 이내입니다.",
        "Enter your room from CRA My Account to see what's left.": "남은 한도를 보려면 CRA My Account에서 확인한 한도를 입력하세요.",
        "Withdrawn this year: %@ — this room comes back on January 1.": "올해 인출액: %@ — 이 한도는 1월 1일에 다시 생깁니다.",
        "No recent losses to watch.": "확인할 최근 손실이 없습니다.",
        "Superficial loss watch": "피상적 손실 확인",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "비등록 계좌에서 손실을 보고 매도한 뒤, 매도 전후 30일 이내에 본인(또는 배우자)이 TFSA나 RRSP를 포함한 어느 계좌에서든 같은 증권을 매수해 계속 보유하면 CRA는 그 손실을 인정하지 않습니다. Orion은 연결된 모든 계좌를 확인합니다. 배우자 계좌는 연결하지 않으면 포함되지 않습니다.",
        "Sold at a loss on %@ in %@": "%@ %@에서 손실 매도",
        "Don't buy %@ in any account until %@ to keep this loss.": "손실을 인정받으려면 %2$@까지 어느 계좌에서도 %1$@을(를) 매수하지 마세요.",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "피상적 손실일 가능성이 높습니다. 30일 이내에 다시 매수해 아직 보유하고 있습니다.",
        "Bought on %@ in %@": "%@ %@에서 매수",
        "Amount in CAD": "금액(CAD)",
        "%@ room available on January 1, %d": "%2$d년 1월 1일 기준 %1$@ 사용 가능 한도",
        "Clear": "지우기",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room에서 확인하세요.",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "최근 Notice of Assessment 또는 CRA My Account에 있는 RRSP 공제 한도를 사용하세요.",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "CRA My Account에서 확인하세요. FHSA 연간 한도는 $8,000에 이월 한도를 더한 금액입니다.",
        "AI Research Snapshot": "AI 리서치 스냅샷",
        "Positive": "긍정적",
        "Mixed": "혼재",
        "Negative": "부정적",
        "What to Watch": "주목할 점",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "학습용으로 AI가 생성한 리서치 요약입니다. 매수나 매도 추천이 아닙니다.",
        "Get a side-by-side comparison with an AI summary": "AI 요약과 함께 나란히 비교하기",
        "Example Portfolio to Explore": "살펴볼 예시 포트폴리오",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "모의 투자에서 사용해 볼 수 있는 학습용 예시이며 추천이 아닙니다. 투자 전에 직접 조사하세요.",
        "Ideas to Explore": "살펴볼 아이디어",
        "Popular names in your interests · not a recommendation": "관심 분야의 인기 종목 · 추천 아님",
        "Help Orion tailor what it explains and shows you": "Orion이 설명하고 보여 주는 내용을 맞춤 설정하세요",
        "Pick the categories you want to follow and learn about": "관심 있고 알아보고 싶은 분야를 선택하세요",
        "Update the categories you follow": "관심 분야 업데이트",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "AI 기능이 꺼져 있습니다. 사용하려면 더보기 → AI 데이터 공유에서 Google Gemini와의 공유를 허용하세요.",
        "Before you use Orion AI": "Orion AI를 사용하기 전에",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "Orion의 AI 기능은 외부 서비스인 Google Gemini로 제공됩니다. 답변을 위해 Orion은 Google에 다음을 보냅니다:",
        "What you type or say to Orion, and any images or files you attach": "Orion에 입력하거나 말한 내용과 첨부한 이미지 또는 파일",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "질문한 종목의 공개 시장 데이터(가격, 기본 지표, 뉴스 헤드라인)",
        "Your language and the investing preferences you chose": "사용 언어와 선택한 투자 성향",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "Orion은 연결된 계좌의 잔액, 보유 종목, 계좌 번호, 이름, 이메일을 AI로 보내지 않습니다.",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AI는 학습과 리서치를 위한 기능입니다. 등록된 투자 자문업자가 아니며 무엇을 사거나 팔지 알려 주지 않습니다.",
        "You can turn this off any time in More → AI Data Sharing.": "더보기 → AI 데이터 공유에서 언제든지 끌 수 있습니다.",
        "Google processes this data under its own terms and may handle it outside Canada.": "Google은 자체 약관에 따라 이 데이터를 처리하며, 캐나다 외부에서 처리할 수 있습니다.",
        "Allow and continue": "허용하고 계속하기",
        "Not now": "나중에",
        "AI Data Sharing": "AI 데이터 공유",
        "Send your AI questions to Google Gemini": "AI 질문을 Google Gemini로 보내기",
        "Disclaimer": "면책 조항",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "Orion Finance는 정보와 교육만 제공합니다. 등록된 투자 자문업자, 딜러 또는 세무 전문가가 아니며, 앱의 어떤 내용도 증권의 매수, 매도 또는 보유를 추천하지 않습니다.",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "AI가 생성한 내용은 틀리거나 오래되었을 수 있습니다. 시장 데이터는 지연될 수 있습니다. 연결된 계좌 데이터는 SnapTrade와 Plaid를 통해 금융기관에서 받아오며 공식 명세서와 다를 수 있습니다.",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "세금 기능은 문제를 찾는 데 도움을 주는 추정치입니다. CRA My Account에서 납입 한도를 확인하고, 결정하기 전에 자격을 갖춘 전문가와 상담하세요.",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "Orion은 계좌를 읽기만 합니다. 거래하거나 자금을 이동하거나 금융기관에서 어떤 것도 변경할 수 없습니다.",
        "My Net Worth": "내 순자산",
        "Net Worth": "순자산",
        "No accounts linked yet": "아직 연결된 계좌가 없습니다",
        "Link your accounts": "계좌 연결하기",
        "Manage linked accounts": "연결된 계좌 관리",
        "Wealthsimple, banks and more · read-only": "Wealthsimple, 은행 등 · 읽기 전용",
        "Investment gain is on positions only": "투자 수익은 보유 종목만 기준으로 합니다",
