        "AI features: Google Gemini, only if you turn them on.": "Funciones de IA: Google Gemini, solo si usted las activa.",
        "Bank accounts: Plaid (read-only).": "Cuentas bancarias: Plaid (solo lectura).",
        "Brokerage accounts: SnapTrade (read-only).": "Cuentas de corretaje: SnapTrade (solo lectura).",
        "Market data: Yahoo Finance and Finnhub. Prices may be delayed.": "Datos de mercado: Yahoo Finance y Finnhub. Los precios pueden tener retraso.",
        "Version": "Versión",
