        "Investment style: %@": "Estilo de inversión: %@",
        "Question %d of %d": "Pregunta %d de %d",
        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "Usted acepta oscilaciones más amplias en busca de crecimiento. Orion le explicará empresas de crecimiento y tendencias más recientes, incluidos sus riesgos.",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "Usted equilibra crecimiento y estabilidad. Orion le explicará tanto empresas de crecimiento como inversiones más estables, y cómo se complementan.",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "Usted prioriza la estabilidad. Cuando Orion le explique algo, dedicará más tiempo a la diversificación, las inversiones de renta y la protección de lo que ya tiene.",
        "Prices often move more than usual around an earnings report.": "Los precios suelen moverse más de lo habitual en torno a la publicación de resultados.",
        "Markets are closed for the weekend": "Los mercados están cerrados el fin de semana",
        "Markets have closed for the day": "Los mercados ya cerraron por hoy",
        "Markets open at 9:30 AM ET": "Los mercados abren a las 9:30 AM ET",
        "Markets are open · close at 4:00 PM ET": "Mercados abiertos · cierran a las 4:00 PM ET",
        "As of %@ ET": "A las %@ ET",
        "Add %@ to watchlist": "Agregar %@ a la lista de seguimiento",
        "%@ added to watchlist": "%@ se agregó a la lista de seguimiento",
        "Added": "Agregado",
        "Dismiss": "Cerrar",
        "Adding %@…": "Agregando %@…",
        "%@ was added here but couldn't be saved to your account.": "%@ se agregó aquí, pero no se pudo guardar en su cuenta.",
        "Added for this session. Sign in to keep your watchlist.": "Agregado para esta sesión. Inicie sesión para conservar su lista de seguimiento.",
        "Couldn't add %@. Check your connection and try again.": "No se pudo agregar %@. Compruebe su conexión e inténtelo de nuevo.",
        "%@ is already in your watchlist.": "%@ ya está en su lista de seguimiento.",
        "D/E": "D/E",
        "ROE": "ROE",
        "Beta": "Beta",
        "P/B": "P/B",
        "P/E": "P/E",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "Margen operativo: la parte de los ingresos que queda después de todos los costos operativos, como salarios, investigación y marketing. Muestra la rentabilidad del negocio principal antes de intereses e impuestos.",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "La parte de los ingresos que queda después del costo directo de producir el producto o servicio. Con un margen bruto del 70 por ciento, de cada $100 en ventas quedan $70 para cubrir todo lo demás.",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "Deuda sobre capital: deuda total dividida por el patrimonio de los accionistas. Un número más alto significa que la empresa depende más del endeudamiento, lo que amplifica tanto las ganancias como los riesgos. Los niveles normales varían mucho según el sector.",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "Rentabilidad sobre el patrimonio: beneficio anual dividido por el patrimonio de los accionistas. Muestra con qué eficiencia la empresa convierte el capital invertido en beneficios. Un ROE muy alto también puede deberse a un endeudamiento elevado.",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "Cuánto ha tendido a moverse la acción en relación con el mercado en general. 1 se mueve con el mercado, por encima de 1 oscila más y por debajo de 1 oscila menos. Describe la volatilidad pasada, no rendimientos futuros.",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "Rentabilidad por dividendo: dividendos anuales por acción divididos por el precio de la acción. Una rentabilidad del 2 por ciento paga unos $2 al año por cada $100 invertidos. Una rentabilidad inusualmente alta puede indicar que el mercado espera un recorte del dividendo.",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "Cuánto crecieron las ventas de la empresa en comparación con un año antes. Muestra la demanda del negocio antes de costos; combínelo con los márgenes para ver si el crecimiento es rentable.",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "Cuánto creció el beneficio por acción en comparación con un año antes. Un crecimiento sostenido suele respaldar una valoración más alta; un solo año fuerte puede deberse a partidas extraordinarias.",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "Relación precio/valor contable: el precio de la acción dividido por el valor contable (activos menos pasivos) por acción de la empresa. Por debajo de 1 significa que el mercado valora la empresa por menos que su patrimonio neto contable. Es más significativa para bancos y negocios con muchos activos que para empresas de software.",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "Relación precio/beneficio: el precio de la acción dividido por el beneficio por acción de la empresa en el último año. Muestra cuántos dólares pagan los inversores por cada dólar de beneficio. Un número más alto suele significar que los inversores esperan un crecimiento más rápido, o que la acción está cara. Es más útil al compararla con empresas similares.",
        "Generate snapshot": "Generar resumen",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "Un breve resumen de investigación sobre %@ escrito por IA: qué impulsa la acción, riesgos clave y qué vigilar. No es una recomendación.",
        "Couldn't generate the snapshot right now.": "No se pudo generar el resumen en este momento.",
