        "Tax Assistant": "Asistente fiscal",
        "TFSA · RRSP · FHSA room and superficial loss watch": "Margen de TFSA · RRSP · FHSA y vigilancia de pérdidas superficiales",
        "%d items need attention": "%d elementos requieren atención",
        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "Solo informativo, no es asesoramiento fiscal. Verifique sus cifras en CRA My Account o con un profesional tributario.",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "Vincule una casa de bolsa para seguir sus aportaciones a TFSA, RRSP y FHSA.",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "No se encontraron cuentas TFSA, RRSP ni FHSA entre sus cuentas vinculadas.",
        "%d contribution room": "Margen de aportación %d",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "Las aportaciones se calculan a partir de sus cuentas vinculadas en este año calendario. Las transferencias entre instituciones no se cuentan. Las aportaciones al RRSP en los primeros 60 días del año pueden aplicarse al año fiscal anterior.",
        "Set room": "Definir margen",
        "Edit room": "Editar margen",
        "Contributed this year": "Aportado este año",
        "Room left": "Margen restante",
        "Over your room by": "Excede su margen en",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "La CRA cobra un 1 por ciento mensual sobre las aportaciones excedentes (%@ en este caso). Retire el excedente para detener la penalización.",
        "Within the $2,000 RRSP over-contribution allowance.": "Dentro de la tolerancia de $2,000 para aportaciones excedentes al RRSP.",
        "Enter your room from CRA My Account to see what's left.": "Introduzca su margen según CRA My Account para ver lo que le queda.",
        "Withdrawn this year: %@ — this room comes back on January 1.": "Retirado este año: %@; este margen se recupera el 1 de enero.",
        "No recent losses to watch.": "No hay pérdidas recientes que vigilar.",
        "Superficial loss watch": "Vigilancia de pérdidas superficiales",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "Si vende con pérdida en una cuenta no registrada y usted (o su cónyuge) compra el mismo valor dentro de los 30 días anteriores o posteriores, en cualquier cuenta, incluida una TFSA o un RRSP, y todavía lo conserva, la CRA no admite la pérdida. Orion revisa todas sus cuentas vinculadas. Las cuentas del cónyuge no se incluyen a menos que estén vinculadas.",
        "Sold at a loss on %@ in %@": "Vendido con pérdida el %@ en %@",
        "Don't buy %@ in any account until %@ to keep this loss.": "No compre %@ en ninguna cuenta hasta el %@ para conservar esta pérdida.",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "Probablemente sea una pérdida superficial: lo volvió a comprar dentro de 30 días y todavía lo conserva.",
        "Bought on %@ in %@": "Comprado el %@ en %@",
        "Amount in CAD": "Importe en CAD",
        "%@ room available on January 1, %d": "Margen de %@ disponible el 1 de enero de %d",
        "Clear": "Borrar",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "Consúltelo en CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "Use el límite de deducción del RRSP de su Notice of Assessment más reciente o de CRA My Account.",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "Consúltelo en CRA My Account. El límite anual de la FHSA es de $8,000 más cualquier margen trasladado.",
        "AI Research Snapshot": "Resumen de investigación con IA",
        "Positive": "Positivo",
        "Mixed": "Mixto",
        "Negative": "Negativo",
        "What to Watch": "Qué vigilar",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "Resumen de investigación generado por IA con fines educativos. No es una recomendación de compra ni de venta.",
        "Get a side-by-side comparison with an AI summary": "Obtenga una comparación lado a lado con un resumen de IA",
        "Example Portfolio to Explore": "Cartera de ejemplo para explorar",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "Un ejemplo educativo para probar en Operaciones simuladas; no es una recomendación. Investigue por su cuenta antes de invertir.",
        "Ideas to Explore": "Ideas para explorar",
        "Popular names in your interests · not a recommendation": "Nombres populares en sus intereses · no es una recomendación",
        "Help Orion tailor what it explains and shows you": "Ayude a Orion a adaptar lo que le explica y le muestra",
        "Pick the categories you want to follow and learn about": "Elija las categorías que desea seguir y conocer",
        "Update the categories you follow": "Actualice las categorías que sigue",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "Las funciones de IA están desactivadas. Para usarlas, permita compartir datos con Google Gemini en Más → Compartir datos con IA.",
        "Before you use Orion AI": "Antes de usar Orion AI",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "Las funciones de IA de Orion funcionan con Google Gemini, un servicio de terceros. Para responderle, Orion envía a Google:",
        "What you type or say to Orion, and any images or files you attach": "Lo que escribe o le dice a Orion, y las imágenes o archivos que adjunte",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "Datos públicos de mercado de las acciones sobre las que pregunta (precios, fundamentales, titulares de noticias)",
        "Your language and the investing preferences you chose": "Su idioma y las preferencias de inversión que eligió",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "Orion no envía a la IA los saldos de sus cuentas vinculadas, posiciones, números de cuenta, nombre ni correo electrónico.",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AI es para educación e investigación. No es un asesor registrado y no le dice qué comprar o vender.",
        "You can turn this off any time in More → AI Data Sharing.": "Puede desactivarlo en cualquier momento en Más → Compartir datos con IA.",
        "Google processes this data under its own terms and may handle it outside Canada.": "Google procesa estos datos según sus propios términos y puede tratarlos fuera de Canadá.",
        "Allow and continue": "Permitir y continuar",
        "Not now": "Ahora no",
        "AI Data Sharing": "Compartir datos con IA",
        "Send your AI questions to Google Gemini": "Enviar sus preguntas de IA a Google Gemini",
        "Disclaimer": "Aviso legal",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "Orion Finance solo ofrece información y educación. No es un asesor de inversiones registrado, un intermediario ni un profesional tributario, y nada en la app constituye una recomendación de comprar, vender o mantener ningún valor.",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "El contenido generado por IA puede ser incorrecto o estar desactualizado. Los datos de mercado pueden tener retraso. Los datos de las cuentas vinculadas provienen de sus instituciones a través de SnapTrade y Plaid y pueden no coincidir con sus estados de cuenta oficiales.",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "Las funciones fiscales son estimaciones para ayudarle a detectar problemas. Confirme su margen de aportación en CRA My Account y consulte a un profesional cualificado antes de tomar decisiones.",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "Orion solo lee sus cuentas. No puede operar, mover dinero ni cambiar nada en sus instituciones.",
