        "Link Wealthsimple, other brokerages or your bank to see your net worth in Orion. Read-only: Orion can never trade or move money, and never sees your passwords.": "Vincule Wealthsimple, otras casas de bolsa o su banco para ver su patrimonio neto en Orion. Solo lectura: Orion nunca puede operar ni mover dinero, y nunca ve sus contraseñas.",
