        "AI features: Google Gemini, only if you turn them on.": "Fonctions IA : Google Gemini, uniquement si vous les activez.",
        "Bank accounts: Plaid (read-only).": "Comptes bancaires : Plaid (lecture seule).",
        "Brokerage accounts: SnapTrade (read-only).": "Comptes de courtage : SnapTrade (lecture seule).",
        "Market data: Yahoo Finance and Finnhub. Prices may be delayed.": "Données de marché : Yahoo Finance et Finnhub. Les cours peuvent être différés.",
        "Version": "Version",
        "About & Data Sources": "À propos et sources de données",
        "Investment style: %@": "Style d'investissement : %@",
        "Question %d of %d": "Question %d sur %d",
        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "Vous acceptez des variations plus importantes en quête de croissance. Orion vous expliquera les entreprises de croissance et les tendances émergentes — y compris leurs risques.",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "Vous équilibrez croissance et stabilité. Orion vous expliquera à la fois les entreprises de croissance et les placements plus stables, et comment ils se complètent.",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "Vous privilégiez la stabilité. Dans ses explications, Orion insistera davantage sur la diversification, les placements de revenu et la protection de vos acquis.",
        "Prices often move more than usual around an earnings report.": "Les cours varient souvent plus que d'habitude autour d'une publication de résultats.",
        "Markets are closed for the weekend": "Les marchés sont fermés pour le week-end",
        "Markets have closed for the day": "Les marchés sont fermés pour aujourd'hui",
        "Markets open at 9:30 AM ET": "Les marchés ouvrent à 9:30 AM (heure de l'Est)",
        "Markets are open · close at 4:00 PM ET": "Marchés ouverts · fermeture à 4:00 PM (heure de l'Est)",
        "As of %@ ET": "À %@ (heure de l'Est)",
        "Add %@ to watchlist": "Ajouter %@ à la liste de suivi",
        "%@ added to watchlist": "%@ ajouté à la liste de suivi",
        "Added": "Ajouté",
        "Dismiss": "Fermer",
        "Adding %@…": "Ajout de %@…",
        "%@ was added here but couldn't be saved to your account.": "%@ a été ajouté ici, mais n'a pas pu être enregistré dans votre compte.",
        "Added for this session. Sign in to keep your watchlist.": "Ajouté pour cette session. Connectez-vous pour conserver votre liste de suivi.",
        "Couldn't add %@. Check your connection and try again.": "Impossible d'ajouter %@. Vérifiez votre connexion et réessayez.",
        "%@ is already in your watchlist.": "%@ est déjà dans votre liste de suivi.",
        "D/E": "D/CP",
        "ROE": "ROE",
        "Beta": "Bêta",
        "P/B": "C/VC",
        "P/E": "C/B",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "Marge d'exploitation : part du chiffre d'affaires restant après tous les coûts d'exploitation, comme les salaires, la recherche et le marketing. Elle montre la rentabilité de l'activité principale avant intérêts et impôts.",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "Part du chiffre d'affaires restant après le coût direct de fabrication du produit ou du service. Avec une marge brute de 70 %, il reste 70 $ sur chaque tranche de 100 $ de ventes pour payer tout le reste.",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "Ratio d'endettement : dette totale divisée par les capitaux propres. Un chiffre plus élevé signifie que l'entreprise dépend davantage de l'emprunt, ce qui amplifie à la fois les gains et les risques. Les niveaux normaux varient fortement selon le secteur.",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "Rendement des capitaux propres : bénéfice annuel divisé par les capitaux propres. Il montre l'efficacité avec laquelle l'entreprise transforme le capital investi en bénéfices. Un ROE très élevé peut aussi provenir d'un fort endettement.",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "Mesure dans laquelle l'action a eu tendance à varier par rapport à l'ensemble du marché. 1 suit le marché, au-dessus de 1 varie davantage, en dessous de 1 varie moins. Elle décrit la volatilité passée, pas les rendements futurs.",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "Rendement du dividende : dividendes annuels par action divisés par le cours de l'action. Un rendement de 2 % rapporte environ 2 $ par an pour chaque tranche de 100 $ investie. Un rendement anormalement élevé peut indiquer que le marché s'attend à une baisse du dividende.",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "Croissance du chiffre d'affaires de l'entreprise par rapport à l'année précédente. Elle reflète la demande avant les coûts — à comparer avec les marges pour voir si la croissance est rentable.",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "Croissance du bénéfice par action par rapport à l'année précédente. Une croissance soutenue tend à justifier une valorisation plus élevée ; une seule bonne année peut résulter d'éléments ponctuels.",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "Ratio cours/valeur comptable : cours de l'action divisé par la valeur comptable (actif moins passif) par action. En dessous de 1, le marché valorise l'entreprise moins que sa valeur nette comptable. Ce ratio est plus pertinent pour les banques et les entreprises à forte intensité d'actifs que pour les éditeurs de logiciels.",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "Ratio cours/bénéfice : cours de l'action divisé par le bénéfice par action de l'entreprise sur la dernière année. Il indique combien de dollars les investisseurs paient pour chaque dollar de bénéfice. Un chiffre élevé signifie souvent que les investisseurs anticipent une croissance plus rapide — ou que l'action est chère. Il est surtout utile en comparaison avec des entreprises similaires.",
        "Generate snapshot": "Générer l'aperçu",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "Un court résumé de recherche sur %@, rédigé par l'IA : ce qui fait bouger l'action, les principaux risques et les points à surveiller. Ceci n'est pas une recommandation.",
