        "Your net worth may be out of date. Tap to fix.": "Votre valeur nette n'est peut-être pas à jour. Touchez pour corriger.",
        "Non-registered": "Non enregistré",
        "Tax Assistant": "Assistant fiscal",
        "TFSA · RRSP · FHSA room and superficial loss watch": "Droits TFSA · RRSP · FHSA et surveillance des pertes apparentes",
        "%d items need attention": "%d éléments nécessitent votre attention",
        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "À titre informatif seulement, pas un conseil fiscal. Vérifiez vos chiffres dans CRA My Account ou auprès d'un fiscaliste.",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "Liez un compte de courtage pour suivre vos cotisations TFSA, RRSP et FHSA.",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "Aucun compte TFSA, RRSP ou FHSA parmi vos comptes liés.",
        "%d contribution room": "Droits de cotisation %d",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "Les cotisations sont calculées à partir de vos comptes liés pour l'année civile en cours. Les transferts entre institutions ne sont pas comptés. Les cotisations RRSP versées dans les 60 premiers jours de l'année peuvent s'appliquer à l'année d'imposition précédente.",
        "Set room": "Définir les droits",
        "Edit room": "Modifier les droits",
        "Contributed this year": "Cotisé cette année",
        "Room left": "Droits restants",
        "Over your room by": "Dépassement des droits de",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "La CRA impose une pénalité de 1 %% par mois sur les cotisations excédentaires (%@ ici). Retirez l'excédent pour arrêter la pénalité.",
        "Within the $2,000 RRSP over-contribution allowance.": "Dans la limite de l'excédent permis de $2,000 du RRSP.",
        "Enter your room from CRA My Account to see what's left.": "Entrez vos droits indiqués dans CRA My Account pour voir ce qu'il reste.",
        "Withdrawn this year: %@ — this room comes back on January 1.": "Retiré cette année : %@ — ces droits seront rétablis le 1er janvier.",
        "No recent losses to watch.": "Aucune perte récente à surveiller.",
        "Superficial loss watch": "Surveillance des pertes apparentes",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "Si vous vendez à perte dans un compte non enregistré et que vous (ou votre conjoint) achetez le même titre dans les 30 jours avant ou après — dans n'importe quel compte, y compris un TFSA ou un RRSP — et le détenez toujours, la CRA refuse la perte. Orion vérifie tous vos comptes liés. Les comptes de votre conjoint ne sont inclus que s'ils sont liés.",
        "Sold at a loss on %@ in %@": "Vendu à perte le %@ dans %@",
        "Don't buy %@ in any account until %@ to keep this loss.": "N'achetez %@ dans aucun compte avant le %@ pour conserver cette perte.",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "Probablement une perte apparente — vous l'avez racheté dans les 30 jours et le détenez toujours.",
        "Bought on %@ in %@": "Acheté le %@ dans %@",
        "Amount in CAD": "Montant en CAD",
        "%@ room available on January 1, %d": "Droits %@ disponibles le 1er janvier %d",
        "Clear": "Effacer",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "Consultez CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "Utilisez le plafond de déduction RRSP indiqué sur votre dernier Notice of Assessment ou dans CRA My Account.",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "Consultez CRA My Account. Le plafond annuel du FHSA est de $8,000, plus tout montant reporté.",
        "AI Research Snapshot": "Aperçu de recherche IA",
        "Positive": "Plutôt positif",
        "Mixed": "Signaux mitigés",
        "Negative": "Plutôt négatif",
        "What to Watch": "À surveiller",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "Résumé de recherche généré par l'IA à des fins éducatives. Ce n'est pas une recommandation d'achat ou de vente.",
        "Get a side-by-side comparison with an AI summary": "Obtenez une comparaison côte à côte avec un résumé IA",
        "Example Portfolio to Explore": "Portefeuille d'exemple à explorer",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "Un exemple éducatif à essayer en simulation boursière — pas une recommandation. Faites vos propres recherches avant d'investir.",
        "Ideas to Explore": "Idées à explorer",
        "Popular names in your interests · not a recommendation": "Titres populaires dans vos centres d'intérêt · pas une recommandation",
        "Help Orion tailor what it explains and shows you": "Aidez Orion à adapter ce qu'il vous explique et vous montre",
        "Pick the categories you want to follow and learn about": "Choisissez les catégories que vous voulez suivre et découvrir",
        "Update the categories you follow": "Mettez à jour les catégories que vous suivez",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "Les fonctions IA sont désactivées. Autorisez le partage avec Google Gemini dans Plus → Partage de données IA pour les utiliser.",
        "Before you use Orion AI": "Avant d'utiliser Orion AI",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "Les fonctions IA d'Orion reposent sur Google Gemini, un service tiers. Pour vous répondre, Orion envoie à Google :",
        "What you type or say to Orion, and any images or files you attach": "Ce que vous écrivez ou dites à Orion, ainsi que les images ou fichiers que vous joignez",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "Les données de marché publiques des actions sur lesquelles vous posez des questions (cours, données fondamentales, titres d'actualité)",
        "Your language and the investing preferences you chose": "Votre langue et les préférences d'investissement que vous avez choisies",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "Orion n'envoie pas à l'IA les soldes, positions, numéros de compte, nom ou e-mail de vos comptes liés.",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AI est destiné à l'apprentissage et à la recherche. Ce n'est pas un conseiller inscrit et il ne vous dit pas quoi acheter ou vendre.",
        "You can turn this off any time in More → AI Data Sharing.": "Vous pouvez désactiver cette option à tout moment dans Plus → Partage de données IA.",
        "Google processes this data under its own terms and may handle it outside Canada.": "Google traite ces données selon ses propres conditions et peut les traiter hors du Canada.",
        "Allow and continue": "Autoriser et continuer",
        "Not now": "Pas maintenant",
        "AI Data Sharing": "Partage de données IA",
        "Send your AI questions to Google Gemini": "Envoyer vos questions IA à Google Gemini",
        "Disclaimer": "Avertissement",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "Orion Finance fournit uniquement de l'information et du contenu éducatif. Ce n'est pas un conseiller en placement inscrit, un courtier ni un fiscaliste, et rien dans l'application ne constitue une recommandation d'acheter, de vendre ou de conserver un titre.",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "Le contenu généré par l'IA peut être erroné ou obsolète. Les données de marché peuvent être différées. Les données des comptes liés proviennent de vos institutions via SnapTrade et Plaid et peuvent ne pas correspondre à vos relevés officiels.",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "Les fonctions fiscales sont des estimations pour vous aider à repérer des problèmes. Confirmez vos droits de cotisation dans CRA My Account et consultez un professionnel qualifié avant de prendre une décision.",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "Orion lit uniquement vos comptes. Il ne peut pas effectuer de transactions, déplacer de l'argent ni modifier quoi que ce soit auprès de vos institutions.",
