        "AI features: Google Gemini, only if you turn them on.": "KI-Funktionen: Google Gemini, nur wenn Sie sie aktivieren.",
        "Bank accounts: Plaid (read-only).": "Bankkonten: Plaid (nur Lesezugriff).",
        "Brokerage accounts: SnapTrade (read-only).": "Depotkonten: SnapTrade (nur Lesezugriff).",
        "Market data: Yahoo Finance and Finnhub. Prices may be delayed.": "Marktdaten: Yahoo Finance und Finnhub. Kurse können verzögert sein.",
