        "About & Data Sources": "Info & Datenquellen",
        "Investment style: %@": "Anlagestil: %@",
        "Question %d of %d": "Frage %d von %d",
        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "Sie nehmen größere Schwankungen in Kauf, um Wachstum anzustreben. Orion erklärt Wachstumsunternehmen und neuere Trends – einschließlich ihrer Risiken.",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "Sie wägen Wachstum und Stabilität ab. Orion erklärt sowohl Wachstumsunternehmen als auch stabilere Anlagen und wie sie zusammenpassen.",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "Für Sie steht Stabilität an erster Stelle. Orion geht in seinen Erklärungen stärker auf Diversifikation, ertragsorientierte Anlagen und den Schutz Ihres Vermögens ein.",
        "Prices often move more than usual around an earnings report.": "Rund um die Veröffentlichung von Quartalszahlen schwanken Kurse oft stärker als üblich.",
        "Markets are closed for the weekend": "Die Märkte sind am Wochenende geschlossen",
