        "Dismiss": "Schließen",
        "Adding %@…": "%@ wird hinzugefügt…",
        "%@ was added here but couldn't be saved to your account.": "%@ wurde hier hinzugefügt, konnte aber nicht in Ihrem Konto gespeichert werden.",
        "Added for this session. Sign in to keep your watchlist.": "Für diese Sitzung hinzugefügt. Melden Sie sich an, um Ihre Watchlist zu behalten.",
        "Couldn't add %@. Check your connection and try again.": "%@ konnte nicht hinzugefügt werden. Prüfen Sie Ihre Verbindung und versuchen Sie es erneut.",
        "%@ is already in your watchlist.": "%@ ist bereits in Ihrer Watchlist.",
        "D/E": "Verschuldungsgrad",
        "ROE": "ROE",
        "Beta": "Beta",
        "P/B": "KBV",
        "P/E": "KGV",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "Operative Marge: der Anteil des Umsatzes, der nach allen Betriebskosten wie Gehältern, Forschung und Marketing übrig bleibt. Sie zeigt, wie profitabel das Kerngeschäft vor Zinsen und Steuern ist.",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "Der Anteil des Umsatzes, der nach den direkten Kosten für die Herstellung des Produkts oder der Dienstleistung übrig bleibt. Bei 70 Prozent Bruttomarge bleiben von je $100 Umsatz $70, um alles Weitere zu bezahlen.",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "Verschuldungsgrad: Gesamtverschuldung geteilt durch das Eigenkapital. Ein höherer Wert bedeutet, dass das Unternehmen stärker auf Fremdkapital setzt, was Gewinne wie Risiken verstärkt. Übliche Werte unterscheiden sich je nach Branche stark.",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "Eigenkapitalrendite: Jahresgewinn geteilt durch das Eigenkapital. Sie zeigt, wie effizient das Unternehmen eingesetztes Kapital in Gewinn umwandelt. Eine sehr hohe ROE kann auch auf hohe Verschuldung zurückgehen.",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "Wie stark sich die Aktie in der Vergangenheit im Verhältnis zum Gesamtmarkt bewegt hat. 1 bedeutet Bewegung mit dem Markt, über 1 stärkere, unter 1 schwächere Schwankungen. Der Wert beschreibt vergangene Schwankungen, nicht künftige Renditen.",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "Dividendenrendite: jährliche Dividende je Aktie geteilt durch den Aktienkurs. Bei 2 Prozent Rendite fließen pro investierten $100 etwa $2 im Jahr. Eine ungewöhnlich hohe Rendite kann bedeuten, dass der Markt eine Kürzung der Dividende erwartet.",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "Wie stark der Umsatz des Unternehmens gegenüber dem Vorjahr gewachsen ist. Das zeigt die Nachfrage vor Kosten – betrachten Sie es zusammen mit den Margen, um zu sehen, ob das Wachstum profitabel ist.",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "Wie stark der Gewinn je Aktie gegenüber dem Vorjahr gewachsen ist. Anhaltendes Wachstum stützt tendenziell eine höhere Bewertung; ein einzelnes starkes Jahr kann auf Einmaleffekte zurückgehen.",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "Kurs-Buchwert-Verhältnis: der Aktienkurs geteilt durch den Buchwert (Vermögen minus Verbindlichkeiten) je Aktie. Unter 1 bedeutet, dass der Markt das Unternehmen niedriger bewertet als sein bilanzielles Reinvermögen. Für Banken und anlageintensive Unternehmen ist es aussagekräftiger als für Softwareunternehmen.",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "Kurs-Gewinn-Verhältnis: der Aktienkurs geteilt durch den Gewinn je Aktie des letzten Jahres. Es zeigt, wie viele Dollar Anleger für jeden Dollar Gewinn zahlen. Ein höherer Wert bedeutet oft, dass Anleger schnelleres Wachstum erwarten – oder dass die Aktie teuer ist. Am aussagekräftigsten ist es im Vergleich mit ähnlichen Unternehmen.",
        "Generate snapshot": "Kurzanalyse erstellen",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "Eine kurze, von KI verfasste Research-Zusammenfassung zu %@: was die Aktie bewegt, wichtige Risiken und worauf zu achten ist. Keine Empfehlung.",
        "Couldn't generate the snapshot right now.": "Die Kurzanalyse konnte gerade nicht erstellt werden.",
        "Explain %@ for %@ with Orion AI": "%@ für %@ mit Orion AI erklären",
        "Retry": "Erneut versuchen",
        "Couldn't load an explanation right now.": "Die Erklärung konnte gerade nicht geladen werden.",
        "Asking Orion…": "Orion wird gefragt…",
        "For %@": "Für %@",
        "Linked Accounts": "Verknüpfte Konten",
        "Bank": "Bank",
        "Disconnect this bank?": "Diese Bank trennen?",
        "%@ accounts will be removed from Orion. Your bank account itself is not affected.": "Die Konten von %@ werden aus Orion entfernt. Ihr Bankkonto selbst ist davon nicht betroffen.",
        "Connect a Bank": "Bank verbinden",
        "Connect Another Bank": "Weitere Bank verbinden",
        "Brokerages connect securely through SnapTrade, banks through Plaid. You sign in on your institution's own page.": "Broker werden sicher über SnapTrade verbunden, Banken über Plaid. Sie melden sich auf der Seite Ihres Instituts an.",
        "Sign in to this bank again to keep it updated.": "Melden Sie sich erneut bei dieser Bank an, damit die Daten aktuell bleiben.",
