        "%d connections need attention": "%d Verbindungen erfordern Ihre Aufmerksamkeit",
        "Your net worth may be out of date. Tap to fix.": "Ihr Nettovermögen ist möglicherweise nicht aktuell. Zum Beheben tippen.",
        "Non-registered": "Nicht registriert",
        "Tax Assistant": "Steuerassistent",
        "TFSA · RRSP · FHSA room and superficial loss watch": "TFSA · RRSP · FHSA: Einzahlungsspielraum und Scheinverlust-Prüfung",
        "%d items need attention": "%d Punkte erfordern Ihre Aufmerksamkeit",
        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "Nur zur Information, keine Steuerberatung. Prüfen Sie Ihre Zahlen in CRA My Account oder bei einer Steuerfachperson.",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "Verknüpfen Sie einen Broker, um TFSA-, RRSP- und FHSA-Einzahlungen zu verfolgen.",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "Unter Ihren verknüpften Konten wurden keine TFSA-, RRSP- oder FHSA-Konten gefunden.",
        "%d contribution room": "Einzahlungsspielraum %d",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "Einzahlungen werden aus Ihren verknüpften Konten für dieses Kalenderjahr gezählt. Überträge zwischen Instituten werden nicht berücksichtigt. RRSP-Einzahlungen in den ersten 60 Tagen des Jahres können dem vorherigen Steuerjahr zugerechnet werden.",
        "Set room": "Spielraum festlegen",
        "Edit room": "Spielraum bearbeiten",
        "Contributed this year": "Dieses Jahr eingezahlt",
        "Room left": "Verbleibender Spielraum",
        "Over your room by": "Spielraum überschritten um",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "Die CRA berechnet 1 Prozent pro Monat auf Überzahlungen (hier %@). Heben Sie den Überschuss ab, um die Strafgebühr zu stoppen.",
        "Within the $2,000 RRSP over-contribution allowance.": "Innerhalb der RRSP-Toleranz von $2,000 für Überzahlungen.",
        "Enter your room from CRA My Account to see what's left.": "Geben Sie Ihren Spielraum aus CRA My Account ein, um zu sehen, was übrig ist.",
        "Withdrawn this year: %@ — this room comes back on January 1.": "Dieses Jahr abgehoben: %@ – dieser Spielraum steht ab dem 1. Januar wieder zur Verfügung.",
        "No recent losses to watch.": "Keine aktuellen Verluste zu beobachten.",
        "Superficial loss watch": "Scheinverlust-Prüfung",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "Wenn Sie in einem nicht registrierten Konto mit Verlust verkaufen und Sie (oder Ihr Ehepartner) dasselbe Wertpapier innerhalb von 30 Tagen davor oder danach kaufen – in einem beliebigen Konto, auch in einem TFSA oder RRSP – und es noch halten, erkennt die CRA den Verlust nicht an. Orion prüft alle Ihre verknüpften Konten. Konten des Ehepartners sind nur enthalten, wenn sie verknüpft sind.",
        "Sold at a loss on %@ in %@": "Am %@ in %@ mit Verlust verkauft",
        "Don't buy %@ in any account until %@ to keep this loss.": "Kaufen Sie %@ bis %@ in keinem Konto, damit dieser Verlust anerkannt bleibt.",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "Wahrscheinlich ein Scheinverlust – Sie haben das Wertpapier innerhalb von 30 Tagen erneut gekauft und halten es noch.",
        "Bought on %@ in %@": "Am %@ in %@ gekauft",
        "Amount in CAD": "Betrag in CAD",
        "%@ room available on January 1, %d": "%@-Spielraum verfügbar am 1. Januar %d",
        "Clear": "Löschen",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "Sie finden ihn in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "Verwenden Sie das RRSP-Abzugslimit aus Ihrem letzten Notice of Assessment oder aus CRA My Account.",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "Sie finden ihn in CRA My Account. Das jährliche FHSA-Limit beträgt $8,000 zuzüglich eines etwaigen Übertrags.",
        "AI Research Snapshot": "KI-Kurzanalyse",
        "Positive": "Positiv",
        "Mixed": "Gemischt",
        "Negative": "Negativ",
        "What to Watch": "Worauf zu achten ist",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "KI-generierte Research-Zusammenfassung zu Lernzwecken. Keine Kauf- oder Verkaufsempfehlung.",
        "Get a side-by-side comparison with an AI summary": "Direkter Vergleich mit KI-Zusammenfassung",
        "Example Portfolio to Explore": "Beispielportfolio zum Entdecken",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "Ein Lernbeispiel zum Ausprobieren im Paper-Trading – keine Empfehlung. Recherchieren Sie selbst, bevor Sie investieren.",
        "Ideas to Explore": "Ideen zum Entdecken",
        "Popular names in your interests · not a recommendation": "Beliebte Werte in Ihren Interessengebieten · keine Empfehlung",
        "Help Orion tailor what it explains and shows you": "Helfen Sie Orion, Erklärungen und Inhalte auf Sie abzustimmen",
        "Pick the categories you want to follow and learn about": "Wählen Sie die Bereiche, denen Sie folgen und über die Sie mehr erfahren möchten",
        "Update the categories you follow": "Aktualisieren Sie die Bereiche, denen Sie folgen",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "KI-Funktionen sind deaktiviert. Erlauben Sie die Weitergabe an Google Gemini unter Mehr → KI-Datenfreigabe, um sie zu nutzen.",
        "Before you use Orion AI": "Bevor Sie Orion AI nutzen",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "Die KI-Funktionen von Orion basieren auf Google Gemini, einem Drittanbieterdienst. Um Ihnen zu antworten, sendet Orion an Google:",
        "What you type or say to Orion, and any images or files you attach": "Was Sie Orion schreiben oder sagen, sowie angehängte Bilder oder Dateien",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "Öffentliche Marktdaten zu den Aktien, nach denen Sie fragen (Kurse, Fundamentaldaten, Schlagzeilen)",
        "Your language and the investing preferences you chose": "Ihre Sprache und die von Ihnen gewählten Anlagepräferenzen",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "Orion sendet keine Kontostände, Positionen, Kontonummern, Namen oder E-Mail-Adressen Ihrer verknüpften Konten an die KI.",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AI dient Lern- und Recherchezwecken. Es ist kein registrierter Anlageberater und sagt Ihnen nicht, was Sie kaufen oder verkaufen sollen.",
        "You can turn this off any time in More → AI Data Sharing.": "Sie können dies jederzeit unter Mehr → KI-Datenfreigabe deaktivieren.",
        "Google processes this data under its own terms and may handle it outside Canada.": "Google verarbeitet diese Daten gemäß eigenen Bedingungen und möglicherweise außerhalb Kanadas.",
        "Allow and continue": "Erlauben und fortfahren",
        "Not now": "Nicht jetzt",
        "AI Data Sharing": "KI-Datenfreigabe",
        "Send your AI questions to Google Gemini": "Ihre KI-Fragen an Google Gemini senden",
        "Disclaimer": "Haftungsausschluss",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "Orion Finance bietet ausschließlich Informationen und Bildungsinhalte. Es ist kein registrierter Anlageberater, Händler oder Steuerberater, und nichts in der App ist eine Empfehlung, ein Wertpapier zu kaufen, zu verkaufen oder zu halten.",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "KI-generierte Inhalte können falsch oder veraltet sein. Marktdaten können verzögert sein. Daten verknüpfter Konten stammen über SnapTrade und Plaid von Ihren Instituten und stimmen möglicherweise nicht mit Ihren offiziellen Auszügen überein.",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "Steuerfunktionen sind Schätzungen, die Ihnen helfen, Probleme zu erkennen. Bestätigen Sie Ihren Einzahlungsspielraum in CRA My Account und sprechen Sie mit einer qualifizierten Fachperson, bevor Sie Entscheidungen treffen.",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "Orion liest Ihre Konten nur. Es kann nicht handeln, kein Geld bewegen und nichts bei Ihren Instituten ändern.",
