        "Bank accounts: Plaid (read-only).": "Contas bancárias: Plaid (somente leitura).",
        "Brokerage accounts: SnapTrade (read-only).": "Contas de corretora: SnapTrade (somente leitura).",
        "Market data: Yahoo Finance and Finnhub. Prices may be delayed.": "Dados de mercado: Yahoo Finance e Finnhub. Os preços podem ter atraso.",
        "Version": "Versão",
        "About & Data Sources": "Sobre e fontes de dados",
        "Investment style: %@": "Perfil de investimento: %@",
        "Question %d of %d": "Pergunta %d de %d",
        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "Você se sente confortável com oscilações maiores em busca de crescimento. O Orion vai explicar empresas de crescimento e tendências mais recentes — incluindo seus riscos.",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "Você equilibra crescimento e estabilidade. O Orion vai explicar tanto empresas de crescimento quanto investimentos mais estáveis, e como eles se complementam.",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "Você prioriza a estabilidade. Ao explicar os assuntos, o Orion vai dedicar mais tempo à diversificação, a investimentos de renda e à proteção do que você já tem.",
        "Prices often move more than usual around an earnings report.": "Os preços costumam oscilar mais do que o normal perto da divulgação de resultados.",
        "Markets are closed for the weekend": "Os mercados estão fechados no fim de semana",
        "Markets have closed for the day": "Os mercados fecharam por hoje",
        "Markets open at 9:30 AM ET": "Os mercados abrem às 9:30 AM ET",
        "Markets are open · close at 4:00 PM ET": "Mercados abertos · fecham às 4:00 PM ET",
        "As of %@ ET": "Às %@ ET",
        "Add %@ to watchlist": "Adicionar %@ à lista de observação",
        "%@ added to watchlist": "%@ adicionado à lista de observação",
        "Added": "Adicionado",
        "Dismiss": "Fechar",
        "Adding %@…": "Adicionando %@…",
        "%@ was added here but couldn't be saved to your account.": "%@ foi adicionado aqui, mas não foi possível salvá-lo na sua conta.",
        "Added for this session. Sign in to keep your watchlist.": "Adicionado nesta sessão. Entre para salvar sua lista de observação.",
        "Couldn't add %@. Check your connection and try again.": "Não foi possível adicionar %@. Verifique sua conexão e tente novamente.",
        "%@ is already in your watchlist.": "%@ já está na sua lista de observação.",
        "D/E": "Dív./PL",
        "ROE": "ROE",
        "Beta": "Beta",
        "P/B": "P/VP",
        "P/E": "P/L",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "Margem operacional: a parcela da receita que sobra depois de todos os custos operacionais, como salários, pesquisa e marketing. Mostra quão lucrativo é o negócio principal antes de juros e impostos.",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "A parcela da receita que sobra depois do custo direto de produzir o produto ou serviço. Uma margem bruta de 70% garante que $70 de cada $100 em vendas fiquem para pagar todo o resto.",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "Dívida/patrimônio líquido: dívida total dividida pelo patrimônio líquido dos acionistas. Um número maior significa que a empresa depende mais de empréstimos, o que amplia tanto os ganhos quanto os riscos. Os níveis normais variam muito entre setores.",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "Retorno sobre o patrimônio líquido: lucro anual dividido pelo patrimônio líquido dos acionistas. Mostra a eficiência com que a empresa transforma o capital investido em lucro. Um ROE muito alto também pode resultar de endividamento elevado.",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "Quanto a ação tende a oscilar em relação ao mercado como um todo. 1 acompanha o mercado, acima de 1 oscila mais, abaixo de 1 oscila menos. Descreve a volatilidade passada, não retornos futuros.",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "Dividend yield: dividendos anuais por ação divididos pelo preço da ação. Um yield de 2% paga cerca de $2 por ano a cada $100 investidos. Um yield excepcionalmente alto pode indicar que o mercado espera um corte nos dividendos.",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "Quanto as vendas da empresa cresceram em relação ao ano anterior. Mostra a demanda pelo negócio antes dos custos — compare com as margens para ver se o crescimento é lucrativo.",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "Quanto o lucro por ação cresceu em relação ao ano anterior. Um crescimento sustentado tende a sustentar uma avaliação mais alta; um único ano forte pode vir de itens não recorrentes.",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "Índice preço/valor patrimonial: o preço da ação dividido pelo valor patrimonial (ativos menos passivos) por ação da empresa. Abaixo de 1 significa que o mercado avalia a empresa abaixo do seu patrimônio líquido contábil. É mais significativo para bancos e empresas com muitos ativos do que para empresas de software.",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "Índice preço/lucro: o preço da ação dividido pelo lucro por ação da empresa no último ano. Mostra quantos dólares os investidores pagam por cada dólar de lucro. Um número maior costuma indicar que os investidores esperam crescimento mais rápido — ou que a ação está cara. É mais útil quando comparado com empresas semelhantes.",
        "Generate snapshot": "Gerar resumo",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "Um breve resumo de pesquisa sobre %@, escrito por IA: o que move a ação, principais riscos e o que acompanhar. Não é uma recomendação.",
        "Couldn't generate the snapshot right now.": "Não foi possível gerar o resumo agora.",
        "Explain %@ for %@ with Orion AI": "Explicar %@ de %@ com o Orion AI",
