        "Your net worth may be out of date. Tap to fix.": "Seu patrimônio líquido pode estar desatualizado. Toque para corrigir.",
        "Non-registered": "Não registrada",
        "Tax Assistant": "Assistente fiscal",
        "TFSA · RRSP · FHSA room and superficial loss watch": "Limites de TFSA · RRSP · FHSA e alerta de perda superficial",
        "%d items need attention": "%d itens precisam de atenção",
        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "Apenas informativo, não é orientação fiscal. Confira seus valores no CRA My Account ou com um profissional de impostos.",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "Vincule uma corretora para acompanhar as contribuições para TFSA, RRSP e FHSA.",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "Nenhuma conta TFSA, RRSP ou FHSA encontrada entre suas contas vinculadas.",
        "%d contribution room": "Limite de contribuição de %d",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "As contribuições são contadas a partir das suas contas vinculadas neste ano civil. Transferências entre instituições não são contadas. Contribuições para RRSP nos primeiros 60 dias do ano podem valer para o ano fiscal anterior.",
        "Set room": "Definir limite",
        "Edit room": "Editar limite",
        "Contributed this year": "Contribuído este ano",
        "Room left": "Limite restante",
        "Over your room by": "Acima do limite em",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "A CRA cobra 1%% ao mês sobre contribuições em excesso (%@ aqui). Retire o excedente para interromper a multa.",
        "Within the $2,000 RRSP over-contribution allowance.": "Dentro da margem de $2,000 para contribuições em excesso no RRSP.",
        "Enter your room from CRA My Account to see what's left.": "Informe seu limite do CRA My Account para ver quanto resta.",
        "Withdrawn this year: %@ — this room comes back on January 1.": "Retirado este ano: %@ — este limite volta em 1º de janeiro.",
        "No recent losses to watch.": "Nenhuma perda recente para acompanhar.",
        "Superficial loss watch": "Alerta de perda superficial",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "Se você vender com prejuízo em uma conta não registrada e você (ou seu cônjuge) comprar o mesmo título nos 30 dias antes ou depois — em qualquer conta, incluindo TFSA ou RRSP — e ainda o mantiver, a CRA não reconhece o prejuízo. O Orion verifica todas as suas contas vinculadas. Contas do cônjuge não são incluídas, a menos que estejam vinculadas.",
        "Sold at a loss on %@ in %@": "Vendido com prejuízo em %@ na conta %@",
        "Don't buy %@ in any account until %@ to keep this loss.": "Não compre %@ em nenhuma conta até %@ para manter este prejuízo.",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "Provável perda superficial — você comprou novamente em até 30 dias e ainda mantém a posição.",
        "Bought on %@ in %@": "Comprado em %@ na conta %@",
        "Amount in CAD": "Valor em CAD",
        "%@ room available on January 1, %d": "Limite de %@ disponível em 1º de janeiro de %d",
        "Clear": "Limpar",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "Encontre no CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "Use o limite de dedução do RRSP indicado no seu Notice of Assessment mais recente ou no CRA My Account.",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "Encontre no CRA My Account. O limite anual do FHSA é de $8,000, mais qualquer valor transportado.",
        "AI Research Snapshot": "Resumo de pesquisa com IA",
        "Positive": "Positivo",
        "Mixed": "Misto",
        "Negative": "Negativo",
        "What to Watch": "O que acompanhar",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "Resumo de pesquisa gerado por IA para fins educacionais. Não é uma recomendação de compra ou venda.",
        "Get a side-by-side comparison with an AI summary": "Veja uma comparação lado a lado com um resumo de IA",
        "Example Portfolio to Explore": "Carteira de exemplo para explorar",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "Um exemplo educacional para testar na Negociação Simulada — não é uma recomendação. Faça sua própria pesquisa antes de investir.",
        "Ideas to Explore": "Ideias para explorar",
        "Popular names in your interests · not a recommendation": "Nomes populares nos seus interesses · não é uma recomendação",
        "Help Orion tailor what it explains and shows you": "Ajude o Orion a adaptar o que ele explica e mostra para você",
        "Pick the categories you want to follow and learn about": "Escolha as categorias que você quer acompanhar e conhecer",
        "Update the categories you follow": "Atualize as categorias que você acompanha",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "Os recursos de IA estão desativados. Permita o compartilhamento com o Google Gemini em Mais → Compartilhamento de dados com IA para usá-los.",
        "Before you use Orion AI": "Antes de usar o Orion AI",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "Os recursos de IA do Orion são fornecidos pelo Google Gemini, um serviço de terceiros. Para responder a você, o Orion envia ao Google:",
        "What you type or say to Orion, and any images or files you attach": "O que você digita ou fala para o Orion, e quaisquer imagens ou arquivos que você anexar",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "Dados públicos de mercado das ações sobre as quais você pergunta (preços, fundamentos, manchetes)",
        "Your language and the investing preferences you chose": "Seu idioma e as preferências de investimento que você escolheu",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "O Orion não envia à IA os saldos, posições, números de conta, nome ou e-mail das suas contas vinculadas.",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "O Orion AI serve para educação e pesquisa. Não é um consultor registrado e não diz o que você deve comprar ou vender.",
        "You can turn this off any time in More → AI Data Sharing.": "Você pode desativar isso a qualquer momento em Mais → Compartilhamento de dados com IA.",
        "Google processes this data under its own terms and may handle it outside Canada.": "O Google processa esses dados de acordo com seus próprios termos e pode tratá-los fora do Canadá.",
        "Allow and continue": "Permitir e continuar",
        "Not now": "Agora não",
        "AI Data Sharing": "Compartilhamento de dados com IA",
        "Send your AI questions to Google Gemini": "Enviar suas perguntas de IA ao Google Gemini",
        "Disclaimer": "Aviso legal",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "O Orion Finance fornece apenas informação e educação. Não é um consultor de investimentos registrado, uma corretora nem um profissional de impostos, e nada no app é uma recomendação para comprar, vender ou manter qualquer título.",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "Conteúdo gerado por IA pode estar errado ou desatualizado. Os dados de mercado podem ter atraso. Os dados das contas vinculadas vêm das suas instituições por meio da SnapTrade e da Plaid e podem não corresponder aos seus extratos oficiais.",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "Os recursos fiscais são estimativas para ajudar você a identificar problemas. Confirme seu limite de contribuição no CRA My Account e converse com um profissional qualificado antes de tomar decisões.",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "O Orion apenas lê suas contas. Ele não pode negociar, movimentar dinheiro nem alterar nada nas suas instituições.",
