        "AI features: Google Gemini, only if you turn them on.": "Funzioni IA: Google Gemini, solo se le attivi.",
        "Bank accounts: Plaid (read-only).": "Conti bancari: Plaid (sola lettura).",
        "Brokerage accounts: SnapTrade (read-only).": "Conti di intermediazione: SnapTrade (sola lettura).",
        "Market data: Yahoo Finance and Finnhub. Prices may be delayed.": "Dati di mercato: Yahoo Finance e Finnhub. I prezzi possono essere in ritardo.",
