        "Investment style: %@": "Stile di investimento: %@",
        "Question %d of %d": "Domanda %d di %d",
        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "Accetti oscillazioni più ampie per puntare alla crescita. Orion ti spiegherà le società in crescita e le nuove tendenze, compresi i relativi rischi.",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "Cerchi un equilibrio tra crescita e stabilità. Orion ti spiegherà sia le società in crescita sia gli investimenti più stabili, e come si combinano.",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "Per te la stabilità viene prima di tutto. Nelle sue spiegazioni Orion dedicherà più spazio alla diversificazione, agli investimenti a reddito e alla protezione di ciò che hai.",
        "Prices often move more than usual around an earnings report.": "Intorno alla pubblicazione degli utili i prezzi tendono a muoversi più del solito.",
        "Markets are closed for the weekend": "I mercati sono chiusi per il fine settimana",
        "Markets have closed for the day": "I mercati hanno chiuso per oggi",
        "Markets open at 9:30 AM ET": "I mercati aprono alle 9:30 AM ET",
        "Markets are open · close at 4:00 PM ET": "Mercati aperti · chiusura alle 4:00 PM ET",
        "As of %@ ET": "Aggiornato alle %@ ET",
        "Add %@ to watchlist": "Aggiungi %@ alla watchlist",
        "%@ added to watchlist": "%@ aggiunto alla watchlist",
        "Added": "Aggiunto",
        "Dismiss": "Chiudi",
        "Adding %@…": "Aggiunta di %@…",
        "%@ was added here but couldn't be saved to your account.": "%@ è stato aggiunto qui, ma non è stato possibile salvarlo nel tuo account.",
        "Added for this session. Sign in to keep your watchlist.": "Aggiunto per questa sessione. Accedi per salvare la tua watchlist.",
        "Couldn't add %@. Check your connection and try again.": "Impossibile aggiungere %@. Controlla la connessione e riprova.",
        "%@ is already in your watchlist.": "%@ è già nella tua watchlist.",
        "D/E": "D/E",
        "ROE": "ROE",
        "Beta": "Beta",
        "P/B": "P/B",
        "P/E": "P/E",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "Margine operativo: la quota di ricavi che resta dopo tutti i costi operativi, come stipendi, ricerca e marketing. Indica quanto è redditizia l'attività principale prima di interessi e imposte.",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "La quota di ricavi che resta dopo il costo diretto del prodotto o servizio. Un margine lordo del 70 per cento lascia $70 ogni $100 di vendite per coprire tutte le altre spese.",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "Rapporto debito/patrimonio netto: debito totale diviso per il patrimonio netto degli azionisti. Un valore più alto indica che la società ricorre di più all'indebitamento, il che amplifica sia i guadagni sia i rischi. I livelli normali variano molto da settore a settore.",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "Rendimento del capitale proprio: utile annuo diviso per il patrimonio netto degli azionisti. Indica con quanta efficienza la società trasforma il capitale investito in utili. Un ROE molto alto può derivare anche da un forte indebitamento.",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "Quanto il titolo ha teso a muoversi rispetto al mercato nel suo complesso. 1 si muove con il mercato, sopra 1 oscilla di più, sotto 1 oscilla di meno. Descrive la volatilità passata, non i rendimenti futuri.",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "Rendimento da dividendo: dividendi annui per azione divisi per il prezzo dell'azione. Un rendimento del 2 per cento corrisponde a circa $2 l'anno ogni $100 investiti. Un rendimento insolitamente alto può indicare che il mercato si aspetta un taglio del dividendo.",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "Di quanto sono cresciute le vendite della società rispetto a un anno prima. Indica la domanda per l'attività al lordo dei costi: abbinala ai margini per capire se la crescita è redditizia.",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "Di quanto è cresciuto l'utile per azione rispetto a un anno prima. Una crescita costante tende a sostenere una valutazione più alta; un singolo anno forte può dipendere da voci non ricorrenti.",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "Rapporto prezzo/valore contabile: il prezzo dell'azione diviso per il valore contabile per azione della società (attività meno passività). Sotto 1 significa che il mercato valuta la società meno del suo patrimonio netto contabile. È più significativo per banche e aziende ad alta intensità di capitale che per le società di software.",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "Rapporto prezzo/utili: il prezzo dell'azione diviso per l'utile per azione della società nell'ultimo anno. Indica quanti dollari gli investitori pagano per ogni dollaro di utile. Un valore più alto spesso significa che gli investitori si aspettano una crescita più rapida, oppure che il titolo è caro. È più utile se confrontato con società simili.",
        "Generate snapshot": "Genera panoramica",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "Un breve riepilogo di ricerca su %@ scritto dall'IA: cosa muove il titolo, i rischi principali e cosa tenere d'occhio. Non è una raccomandazione.",
        "Couldn't generate the snapshot right now.": "Impossibile generare la panoramica al momento.",
        "Explain %@ for %@ with Orion AI": "Spiega %1$@ di %2$@ con Orion AI",
        "Retry": "Riprova",
        "Couldn't load an explanation right now.": "Impossibile caricare una spiegazione al momento.",
