        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "Solo a scopo informativo, non è consulenza fiscale. Verifica i tuoi importi in CRA My Account o con un professionista fiscale.",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "Collega un broker per monitorare i contributi TFSA, RRSP e FHSA.",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "Nessun conto TFSA, RRSP o FHSA tra i tuoi conti collegati.",
        "%d contribution room": "Spazio contributivo %d",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "I contributi sono calcolati dai tuoi conti collegati per l'anno solare in corso. I trasferimenti tra istituti non sono conteggiati. I contributi RRSP versati nei primi 60 giorni dell'anno possono essere imputati all'anno fiscale precedente.",
