        "Room left": "Spazio residuo",
        "Over your room by": "Oltre lo spazio di",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "La CRA applica una penale dell'1 per cento al mese sui contributi in eccesso (qui %@). Preleva l'eccedenza per interrompere la penale.",
        "Within the $2,000 RRSP over-contribution allowance.": "Entro la tolleranza di $2,000 per i contributi RRSP in eccesso.",
        "Enter your room from CRA My Account to see what's left.": "Inserisci il tuo spazio da CRA My Account per vedere quanto ne resta.",
        "Withdrawn this year: %@ — this room comes back on January 1.": "Prelevato quest'anno: %@. Questo spazio torna disponibile il 1° gennaio.",
        "No recent losses to watch.": "Nessuna perdita recente da monitorare.",
        "Superficial loss watch": "Monitoraggio perdite apparenti",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "Se vendi in perdita in un conto non registrato e tu (o il tuo coniuge) acquisti lo stesso titolo nei 30 giorni prima o dopo, in qualsiasi conto, compresi TFSA o RRSP, e lo detieni ancora, la CRA non riconosce la perdita. Orion controlla tutti i tuoi conti collegati. I conti del coniuge non sono inclusi se non sono collegati.",
        "Sold at a loss on %@ in %@": "Venduto in perdita il %@ in %@",
        "Don't buy %@ in any account until %@ to keep this loss.": "Non acquistare %@ in nessun conto fino al %@ per mantenere questa perdita.",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "Probabile perdita apparente: l'hai riacquistato entro 30 giorni e lo detieni ancora.",
        "Bought on %@ in %@": "Acquistato il %@ in %@",
        "Amount in CAD": "Importo in CAD",
        "%@ room available on January 1, %d": "Spazio %@ disponibile al 1° gennaio %d",
        "Clear": "Cancella",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "Lo trovi in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "Usa il limite di deduzione RRSP indicato nel tuo ultimo Notice of Assessment o in CRA My Account.",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "Lo trovi in CRA My Account. Il limite annuo FHSA è di $8,000 più l'eventuale importo riportato.",
        "AI Research Snapshot": "Panoramica di ricerca IA",
        "Positive": "Positivo",
        "Mixed": "Contrastante",
        "Negative": "Negativo",
        "What to Watch": "Da tenere d'occhio",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "Riepilogo di ricerca generato dall'IA a scopo formativo. Non è una raccomandazione di acquisto o vendita.",
        "Get a side-by-side comparison with an AI summary": "Confronto affiancato con un riepilogo IA",
        "Example Portfolio to Explore": "Portafoglio di esempio da esplorare",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "Un esempio formativo da provare nel trading simulato, non una raccomandazione. Fai le tue ricerche prima di investire.",
        "Ideas to Explore": "Idee da esplorare",
        "Popular names in your interests · not a recommendation": "Titoli popolari nei tuoi interessi · non è una raccomandazione",
        "Help Orion tailor what it explains and shows you": "Aiuta Orion ad adattare ciò che ti spiega e ti mostra",
        "Pick the categories you want to follow and learn about": "Scegli le categorie che vuoi seguire e approfondire",
        "Update the categories you follow": "Aggiorna le categorie che segui",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "Le funzioni IA sono disattivate. Per usarle, consenti la condivisione con Google Gemini in Altro → Condivisione dati IA.",
        "Before you use Orion AI": "Prima di usare Orion AI",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "Le funzioni IA di Orion sono basate su Google Gemini, un servizio di terze parti. Per risponderti, Orion invia a Google:",
        "What you type or say to Orion, and any images or files you attach": "Ciò che scrivi o dici a Orion, e le immagini o i file che alleghi",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "Dati di mercato pubblici sui titoli di cui chiedi (prezzi, fondamentali, titoli delle notizie)",
        "Your language and the investing preferences you chose": "La tua lingua e le preferenze di investimento che hai scelto",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "Orion non invia all'IA i saldi, le posizioni e i numeri dei tuoi conti collegati, né il tuo nome o la tua email.",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AI serve per formazione e ricerca. Non è un consulente registrato e non ti dice cosa comprare o vendere.",
        "You can turn this off any time in More → AI Data Sharing.": "Puoi disattivarla in qualsiasi momento in Altro → Condivisione dati IA.",
        "Google processes this data under its own terms and may handle it outside Canada.": "Google tratta questi dati secondo i propri termini e potrebbe gestirli al di fuori del Canada.",
        "Allow and continue": "Consenti e continua",
        "Not now": "Non ora",
        "AI Data Sharing": "Condivisione dati IA",
        "Send your AI questions to Google Gemini": "Invia le tue domande IA a Google Gemini",
        "Disclaimer": "Esclusione di responsabilità",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "Orion Finance fornisce solo informazioni e contenuti formativi. Non è un consulente finanziario registrato, un intermediario o un professionista fiscale, e nulla nell'app costituisce una raccomandazione ad acquistare, vendere o mantenere qualsiasi titolo.",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "I contenuti generati dall'IA possono essere errati o non aggiornati. I dati di mercato possono essere in ritardo. I dati dei conti collegati provengono dai tuoi istituti tramite SnapTrade e Plaid e potrebbero non corrispondere ai tuoi estratti conto ufficiali.",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "Le funzioni fiscali sono stime per aiutarti a individuare eventuali problemi. Verifica il tuo spazio contributivo in CRA My Account e rivolgiti a un professionista qualificato prima di prendere decisioni.",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "Orion legge soltanto i tuoi conti. Non può effettuare operazioni, spostare denaro o modificare nulla presso i tuoi istituti.",
