        "Data sources": "Источники данных",
        "AI features: Google Gemini, only if you turn them on.": "Функции ИИ: Google Gemini, только если вы их включите.",
        "Bank accounts: Plaid (read-only).": "Банковские счета: Plaid (только чтение).",
        "Brokerage accounts: SnapTrade (read-only).": "Брокерские счета: SnapTrade (только чтение).",
        "Market data: Yahoo Finance and Finnhub. Prices may be delayed.": "Рыночные данные: Yahoo Finance и Finnhub. Цены могут быть с задержкой.",
        "Version": "Версия",
        "About & Data Sources": "О приложении и источники данных",
        "Investment style: %@": "Инвестиционный стиль: %@",
        "Question %d of %d": "Вопрос %d из %d",
        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "Вы готовы к более сильным колебаниям ради роста. Orion будет рассказывать о компаниях роста и новых тенденциях — включая их риски.",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "Вы сочетаете рост и стабильность. Orion будет рассказывать и о компаниях роста, и о более стабильных инвестициях, а также о том, как они дополняют друг друга.",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "Для вас на первом месте стабильность. Объясняя что-либо, Orion будет уделять больше внимания диверсификации, доходным инвестициям и сохранению того, что у вас есть.",
        "Prices often move more than usual around an earnings report.": "Вокруг публикации квартального отчёта цены часто меняются сильнее обычного.",
        "Markets are closed for the weekend": "Рынки закрыты на выходные",
        "Markets have closed for the day": "Торги на сегодня завершены",
        "Markets open at 9:30 AM ET": "Рынки открываются в 9:30 AM ET",
        "Markets are open · close at 4:00 PM ET": "Рынки открыты · закрытие в 4:00 PM ET",
        "As of %@ ET": "По состоянию на %@ ET",
        "Add %@ to watchlist": "Добавить %@ в список наблюдения",
        "%@ added to watchlist": "%@ добавлен в список наблюдения",
        "Added": "Добавлено",
        "Dismiss": "Закрыть",
        "Adding %@…": "Добавление %@…",
        "%@ was added here but couldn't be saved to your account.": "%@ добавлен здесь, но не удалось сохранить его в вашем аккаунте.",
        "Added for this session. Sign in to keep your watchlist.": "Добавлено на этот сеанс. Войдите, чтобы сохранить список наблюдения.",
        "Couldn't add %@. Check your connection and try again.": "Не удалось добавить %@. Проверьте подключение и повторите попытку.",
        "%@ is already in your watchlist.": "%@ уже есть в вашем списке наблюдения.",
        "D/E": "Долг/капитал",
        "ROE": "ROE",
        "Beta": "Beta",
        "P/B": "P/B",
        "P/E": "P/E",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "Операционная маржа: доля выручки, остающаяся после всех операционных расходов, таких как зарплаты, исследования и маркетинг. Показывает прибыльность основного бизнеса до процентов и налогов.",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "Доля выручки, остающаяся после прямых затрат на производство товара или услуги. Валовая маржа 70% означает, что из каждых $100 продаж $70 остаётся на все прочие расходы.",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "Долг к капиталу: общий долг, делённый на собственный капитал акционеров. Чем выше значение, тем больше компания опирается на заёмные средства, что усиливает и доходы, и риски. Нормальный уровень сильно различается по отраслям.",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "Рентабельность капитала: годовая прибыль, делённая на собственный капитал акционеров. Показывает, насколько эффективно компания превращает вложенный капитал в прибыль. Очень высокий ROE может быть следствием большой долговой нагрузки.",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "Насколько сильно акция обычно движется относительно рынка в целом. 1 — движется вместе с рынком, выше 1 — колеблется сильнее, ниже 1 — слабее. Описывает прошлую волатильность, а не будущую доходность.",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "Дивидендная доходность: годовые дивиденды на акцию, делённые на цену акции. Доходность 2% означает примерно $2 в год на каждые $100 вложений. Необычно высокая доходность может означать, что рынок ожидает сокращения дивидендов.",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "Насколько выросли продажи компании по сравнению с прошлым годом. Показывает спрос на бизнес без учёта затрат — смотрите вместе с маржой, чтобы понять, прибылен ли рост.",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "Насколько выросла прибыль на акцию по сравнению с прошлым годом. Устойчивый рост обычно поддерживает более высокую оценку; один сильный год может быть результатом разовых статей.",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "Цена к балансовой стоимости: цена акции, делённая на балансовую стоимость компании (активы минус обязательства) на акцию. Значение ниже 1 означает, что рынок оценивает компанию дешевле её бухгалтерских чистых активов. Этот показатель важнее для банков и компаний с большими активами, чем для софтверных компаний.",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "Цена к прибыли: цена акции, делённая на прибыль компании на акцию за последний год. Показывает, сколько долларов инвесторы платят за каждый доллар прибыли. Более высокое значение часто означает, что инвесторы ждут более быстрого роста — или что акция дорогая. Полезнее всего в сравнении с похожими компаниями.",
        "Generate snapshot": "Создать обзор",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "Краткое исследовательское резюме по %@, написанное ИИ: что движет акцией, ключевые риски и на что обратить внимание. Не является рекомендацией.",
        "Couldn't generate the snapshot right now.": "Сейчас не удалось создать обзор.",
        "Explain %@ for %@ with Orion AI": "Объяснить %@ для %@ с Orion AI",
        "Retry": "Повторить",
        "Couldn't load an explanation right now.": "Сейчас не удалось загрузить объяснение.",
        "Asking Orion…": "Спрашиваем Orion…",
