        "Linked Accounts": "Подключённые счета",
        "Bank": "Банк",
        "Disconnect this bank?": "Отключить этот банк?",
        "%@ accounts will be removed from Orion. Your bank account itself is not affected.": "Счета %@ будут удалены из Orion. Сам банковский счёт не затрагивается.",
        "Connect a Bank": "Подключить банк",
        "Connect Another Bank": "Подключить другой банк",
        "Brokerages connect securely through SnapTrade, banks through Plaid. You sign in on your institution's own page.": "Брокеры подключаются безопасно через SnapTrade, банки — через Plaid. Вы входите на собственной странице своего учреждения.",
        "Sign in to this bank again to keep it updated.": "Войдите в этот банк снова, чтобы данные продолжали обновляться.",
        "Couldn't load this bank right now.": "Сейчас не удалось загрузить этот банк.",
