        "Total": "Итого",
        "By institution": "По учреждениям",
        "Show total": "Показать итог",
        "Split by institution": "Разбить по учреждениям",
        "%@ needs you to sign in again": "%@: требуется повторный вход",
        "%@ hasn't updated since %@": "Данные %@ не обновлялись с %@",
        "%@ hasn't updated recently": "Данные %@ давно не обновлялись",
        "%@ couldn't be loaded": "Не удалось загрузить %@",
        "Account connection": "Подключение счёта",
        "%d connections need attention": "Подключений, требующих внимания: %d",
        "Your net worth may be out of date. Tap to fix.": "Ваш чистый капитал может быть неактуален. Нажмите, чтобы исправить.",
        "Non-registered": "Незарегистрированный",
        "Tax Assistant": "Налоговый помощник",
        "TFSA · RRSP · FHSA room and superficial loss watch": "Лимиты TFSA · RRSP · FHSA и контроль фиктивных убытков",
        "%d items need attention": "Пунктов, требующих внимания: %d",
        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "Только для информации, не налоговая консультация. Проверьте свои данные в CRA My Account или у налогового специалиста.",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "Подключите брокерский счёт, чтобы отслеживать взносы в TFSA, RRSP и FHSA.",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "Среди подключённых счетов нет счетов TFSA, RRSP или FHSA.",
        "%d contribution room": "Лимит взносов на %d год",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "Взносы учитываются по подключённым счетам за текущий календарный год. Переводы между учреждениями не учитываются. Взносы в RRSP за первые 60 дней года можно отнести к предыдущему налоговому году.",
        "Set room": "Указать лимит",
        "Edit room": "Изменить лимит",
        "Contributed this year": "Внесено в этом году",
        "Room left": "Остаток лимита",
        "Over your room by": "Превышение лимита на",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "CRA взимает 1 процент в месяц с суммы превышения лимита взносов (здесь %@). Снимите излишек, чтобы остановить начисление штрафа.",
        "Within the $2,000 RRSP over-contribution allowance.": "В пределах допустимого превышения RRSP в $2,000.",
        "Enter your room from CRA My Account to see what's left.": "Укажите свой лимит из CRA My Account, чтобы увидеть остаток.",
        "Withdrawn this year: %@ — this room comes back on January 1.": "Снято в этом году: %@ — этот лимит восстановится 1 января.",
        "No recent losses to watch.": "Нет недавних убытков, требующих внимания.",
        "Superficial loss watch": "Контроль фиктивных убытков",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "Если вы продаёте с убытком на незарегистрированном счёте, а вы (или ваш супруг либо супруга) покупаете ту же ценную бумагу в течение 30 дней до или после продажи — на любом счёте, включая TFSA или RRSP, — и продолжаете её держать, CRA не признаёт этот убыток. Orion проверяет все ваши подключённые счета. Счета супруга или супруги не учитываются, если они не подключены.",
        "Sold at a loss on %@ in %@": "Продано с убытком %@ на счёте %@",
        "Don't buy %@ in any account until %@ to keep this loss.": "Не покупайте %@ ни на одном счёте до %@, чтобы сохранить этот убыток.",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "Вероятно, фиктивный убыток — вы купили бумагу снова в течение 30 дней и всё ещё держите её.",
        "Bought on %@ in %@": "Куплено %@ на счёте %@",
        "Amount in CAD": "Сумма в CAD",
        "%@ room available on January 1, %d": "Лимит %@ на 1 января %d г.",
        "Clear": "Очистить",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "Найдите его в CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "Используйте лимит вычета RRSP из последнего Notice of Assessment или из CRA My Account.",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "Найдите его в CRA My Account. Годовой лимит FHSA — $8,000 плюс перенесённый неиспользованный лимит.",
        "AI Research Snapshot": "ИИ-обзор для исследования",
        "Positive": "Скорее позитивно",
        "Mixed": "Смешанные сигналы",
        "Negative": "Скорее негативно",
        "What to Watch": "На что обратить внимание",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "Исследовательское резюме, созданное ИИ в образовательных целях. Не является рекомендацией покупать или продавать.",
        "Get a side-by-side comparison with an AI summary": "Сравнение бок о бок с резюме от ИИ",
        "Example Portfolio to Explore": "Пример портфеля для изучения",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "Учебный пример, который можно попробовать в демо-торговле, — не рекомендация. Проведите собственное исследование, прежде чем инвестировать.",
        "Ideas to Explore": "Идеи для изучения",
        "Popular names in your interests · not a recommendation": "Популярные бумаги в ваших сферах интересов · не рекомендация",
        "Help Orion tailor what it explains and shows you": "Помогите Orion подобрать то, что он объясняет и показывает вам",
        "Pick the categories you want to follow and learn about": "Выберите категории, за которыми хотите следить и о которых хотите узнать",
        "Update the categories you follow": "Обновите категории, за которыми вы следите",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "Функции ИИ отключены. Чтобы использовать их, разрешите передачу данных в Google Gemini в разделе Ещё → Передача данных ИИ.",
        "Before you use Orion AI": "Перед использованием Orion AI",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "Функции ИИ в Orion работают на основе Google Gemini — стороннего сервиса. Чтобы ответить вам, Orion отправляет в Google:",
        "What you type or say to Orion, and any images or files you attach": "То, что вы пишете или говорите Orion, а также прикреплённые изображения и файлы",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "Открытые рыночные данные по акциям, о которых вы спрашиваете (цены, фундаментальные показатели, заголовки новостей)",
        "Your language and the investing preferences you chose": "Ваш язык и выбранные вами инвестиционные предпочтения",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "Orion не передаёт ИИ балансы и активы ваших подключённых счетов, номера счетов, имя или адрес электронной почты.",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AI предназначен для обучения и исследований. Это не зарегистрированный консультант, и он не говорит вам, что покупать или продавать.",
        "You can turn this off any time in More → AI Data Sharing.": "Это можно отключить в любой момент в разделе Ещё → Передача данных ИИ.",
        "Google processes this data under its own terms and may handle it outside Canada.": "Google обрабатывает эти данные на собственных условиях и может обрабатывать их за пределами Канады.",
        "Allow and continue": "Разрешить и продолжить",
        "Not now": "Не сейчас",
        "AI Data Sharing": "Передача данных ИИ",
        "Send your AI questions to Google Gemini": "Отправлять ваши вопросы ИИ в Google Gemini",
        "Disclaimer": "Отказ от ответственности",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "Orion Finance предоставляет только информацию и обучающие материалы. Приложение не является зарегистрированным инвестиционным консультантом, дилером или налоговым специалистом, и ничто в нём не является рекомендацией покупать, продавать или держать какие-либо ценные бумаги.",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "Контент, созданный ИИ, может быть ошибочным или устаревшим. Рыночные данные могут поступать с задержкой. Данные подключённых счетов поступают от ваших учреждений через SnapTrade и Plaid и могут не совпадать с официальными выписками.",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "Налоговые функции дают оценки, помогающие заметить проблемы. Проверьте свой лимит взносов в CRA My Account и проконсультируйтесь с квалифицированным специалистом, прежде чем принимать решения.",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "Orion только читает ваши счета. Он не может совершать сделки, перемещать деньги или что-либо менять в ваших учреждениях.",
