        "AI features: Google Gemini, only if you turn them on.": "ميزات الذكاء الاصطناعي: Google Gemini، فقط إذا قمت بتفعيلها.",
        "Bank accounts: Plaid (read-only).": "الحسابات المصرفية: Plaid (قراءة فقط).",
        "Brokerage accounts: SnapTrade (read-only).": "حسابات الوساطة: SnapTrade (قراءة فقط).",
        "Market data: Yahoo Finance and Finnhub. Prices may be delayed.": "بيانات السوق: Yahoo Finance وFinnhub. قد تكون الأسعار متأخرة.",
        "Version": "الإصدار",
        "About & Data Sources": "حول التطبيق ومصادر البيانات",
        "Investment style: %@": "أسلوب الاستثمار: %@",
        "Question %d of %d": "السؤال %d من %d",
        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "أنت مرتاح لتقلبات أكبر سعيًا وراء النمو. سيشرح Orion شركات النمو والاتجاهات الأحدث — بما في ذلك مخاطرها.",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "أنت توازن بين النمو والاستقرار. سيشرح Orion كلًّا من شركات النمو والاستثمارات الأكثر استقرارًا، وكيف تتكامل معًا.",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "أنت تضع الاستقرار أولًا. عندما يشرح Orion الأمور، سيخصص وقتًا أطول للتنويع والاستثمارات المدرّة للدخل وحماية ما تملكه.",
        "Prices often move more than usual around an earnings report.": "غالبًا ما تتحرك الأسعار أكثر من المعتاد حول موعد إعلان الأرباح.",
        "Markets are closed for the weekend": "الأسواق مغلقة لعطلة نهاية الأسبوع",
        "Markets have closed for the day": "أغلقت الأسواق لهذا اليوم",
        "Markets open at 9:30 AM ET": "تفتح الأسواق الساعة 9:30 AM بتوقيت ET",
        "Markets are open · close at 4:00 PM ET": "الأسواق مفتوحة · تغلق الساعة 4:00 PM بتوقيت ET",
        "As of %@ ET": "حتى %@ بتوقيت ET",
        "Add %@ to watchlist": "إضافة %@ إلى قائمة المتابعة",
        "%@ added to watchlist": "تمت إضافة %@ إلى قائمة المتابعة",
        "Added": "تمت الإضافة",
        "Dismiss": "إغلاق",
        "Adding %@…": "جارٍ إضافة %@…",
        "%@ was added here but couldn't be saved to your account.": "تمت إضافة %@ هنا لكن تعذّر حفظه في حسابك.",
        "Added for this session. Sign in to keep your watchlist.": "تمت الإضافة لهذه الجلسة. سجّل الدخول للاحتفاظ بقائمة المتابعة.",
        "Couldn't add %@. Check your connection and try again.": "تعذّرت إضافة %@. تحقق من اتصالك وحاول مرة أخرى.",
        "%@ is already in your watchlist.": "%@ موجود بالفعل في قائمة متابعتك.",
        "D/E": "الدين/حقوق الملكية",
        "ROE": "ROE",
        "Beta": "Beta",
        "P/B": "السعر/القيمة الدفترية",
        "P/E": "السعر/الربحية",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "هامش التشغيل: نسبة الإيرادات المتبقية بعد جميع تكاليف التشغيل مثل الرواتب والبحث والتسويق. يوضح مدى ربحية النشاط الأساسي قبل الفوائد والضرائب.",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "نسبة الإيرادات المتبقية بعد التكلفة المباشرة لإنتاج المنتج أو الخدمة. هامش إجمالي بنسبة 70% يعني الاحتفاظ بـ $70 من كل $100 من المبيعات لتغطية كل ما عدا ذلك.",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "نسبة الدين إلى حقوق الملكية: إجمالي الديون مقسومًا على حقوق المساهمين. كلما ارتفع الرقم زاد اعتماد الشركة على الاقتراض، مما يضخّم المكاسب والمخاطر معًا. تختلف المستويات الطبيعية كثيرًا بحسب القطاع.",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "العائد على حقوق الملكية: الربح السنوي مقسومًا على حقوق المساهمين. يوضح مدى كفاءة الشركة في تحويل رأس المال المستثمر إلى أرباح. قد ينتج ارتفاع ROE الشديد أيضًا عن الاقتراض الكبير.",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "مدى ميل السهم إلى التحرك مقارنةً بالسوق ككل. القيمة 1 تعني التحرك مع السوق، وأعلى من 1 تقلبات أكبر، وأقل من 1 تقلبات أقل. يصف التقلبات السابقة، لا العوائد المستقبلية.",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "عائد التوزيعات: التوزيعات السنوية للسهم مقسومة على سعر السهم. عائد بنسبة 2% يدفع نحو $2 سنويًا عن كل $100 مستثمرة. قد يعني العائد المرتفع بشكل غير معتاد أن السوق يتوقع خفض التوزيعات.",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "مقدار نمو مبيعات الشركة مقارنةً بالعام السابق. يوضح الطلب على النشاط قبل احتساب التكاليف — قارنه بالهوامش لمعرفة ما إذا كان النمو مربحًا.",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "مقدار نمو ربحية السهم مقارنةً بالعام السابق. يميل النمو المستدام إلى دعم تقييم أعلى؛ وقد ينتج عام واحد قوي عن بنود غير متكررة.",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "نسبة السعر إلى القيمة الدفترية: سعر السهم مقسومًا على القيمة الدفترية للسهم (الأصول ناقص الالتزامات). أقل من 1 يعني أن السوق يقيّم الشركة بأقل من صافي قيمتها المحاسبية. وهي أكثر دلالة للبنوك والشركات كثيفة الأصول منها لشركات البرمجيات.",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "نسبة السعر إلى الربحية: سعر السهم مقسومًا على ربحية السهم خلال العام الماضي. توضح كم دولارًا يدفعه المستثمرون مقابل كل دولار من الأرباح. غالبًا ما يعني الرقم الأعلى أن المستثمرين يتوقعون نموًا أسرع — أو أن السهم مرتفع الثمن. وتكون أكثر فائدة عند المقارنة بشركات مماثلة.",
        "Generate snapshot": "إنشاء ملخص سريع",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "ملخص بحثي قصير كتبه الذكاء الاصطناعي عن %@: ما الذي يحرّك السهم، والمخاطر الرئيسية، وما يجدر متابعته. ليس توصية.",
        "Couldn't generate the snapshot right now.": "تعذّر إنشاء الملخص السريع حاليًا.",
        "Explain %@ for %@ with Orion AI": "اشرح %@ لسهم %@ باستخدام Orion AI",
        "Retry": "إعادة المحاولة",
        "Couldn't load an explanation right now.": "تعذّر تحميل الشرح حاليًا.",
        "Asking Orion…": "جارٍ سؤال Orion…",
        "For %@": "لـ %@",
        "Linked Accounts": "الحسابات المرتبطة",
        "Bank": "البنك",
        "Disconnect this bank?": "فصل هذا البنك؟",
        "%@ accounts will be removed from Orion. Your bank account itself is not affected.": "ستتم إزالة حسابات %@ من Orion. لن يتأثر حسابك المصرفي نفسه.",
        "Connect a Bank": "ربط بنك",
        "Connect Another Bank": "ربط بنك آخر",
        "Brokerages connect securely through SnapTrade, banks through Plaid. You sign in on your institution's own page.": "تتصل شركات الوساطة بأمان عبر SnapTrade، والبنوك عبر Plaid. تسجّل الدخول على الصفحة الخاصة بمؤسستك.",
        "Sign in to this bank again to keep it updated.": "سجّل الدخول إلى هذا البنك مجددًا لإبقائه محدّثًا.",
        "Couldn't load this bank right now.": "تعذّر تحميل هذا البنك حاليًا.",
