        "By institution": "حسب المؤسسة",
        "Show total": "عرض الإجمالي",
        "Split by institution": "التقسيم حسب المؤسسة",
        "%@ needs you to sign in again": "يحتاج %@ إلى تسجيل الدخول مجددًا",
        "%@ hasn't updated since %@": "لم يتم تحديث %@ منذ %@",
        "%@ hasn't updated recently": "لم يتم تحديث %@ مؤخرًا",
        "%@ couldn't be loaded": "تعذّر تحميل %@",
        "Account connection": "اتصال الحساب",
        "%d connections need attention": "%d اتصالات تحتاج إلى انتباه",
        "Your net worth may be out of date. Tap to fix.": "قد لا تكون صافي ثروتك محدّثة. اضغط للإصلاح.",
        "Non-registered": "غير مسجّل",
        "Tax Assistant": "مساعد الضرائب",
        "TFSA · RRSP · FHSA room and superficial loss watch": "سقف TFSA · RRSP · FHSA ومراقبة الخسارة الصورية",
        "%d items need attention": "%d عناصر تحتاج إلى انتباه",
        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "للمعلومات فقط، وليست نصيحة ضريبية. تحقق من أرقامك في CRA My Account أو مع مختص ضرائب.",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "اربط حساب وساطة لتتبّع مساهمات TFSA وRRSP وFHSA.",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "لم يتم العثور على حسابات TFSA أو RRSP أو FHSA ضمن حساباتك المرتبطة.",
        "%d contribution room": "سقف المساهمة لعام %d",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "تُحتسب المساهمات من حساباتك المرتبطة خلال هذه السنة الميلادية. لا تُحتسب التحويلات بين المؤسسات. يمكن تطبيق مساهمات RRSP في أول 60 يومًا من السنة على السنة الضريبية السابقة.",
        "Set room": "تعيين السقف",
        "Edit room": "تعديل السقف",
        "Contributed this year": "المساهمات هذا العام",
        "Room left": "السقف المتبقي",
        "Over your room by": "تجاوز السقف بمقدار",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "تفرض CRA غرامة 1%% شهريًا على المساهمات الزائدة (%@ هنا). اسحب المبلغ الزائد لإيقاف الغرامة.",
        "Within the $2,000 RRSP over-contribution allowance.": "ضمن هامش السماح البالغ $2,000 للمساهمة الزائدة في RRSP.",
        "Enter your room from CRA My Account to see what's left.": "أدخل سقفك من CRA My Account لمعرفة المتبقي.",
        "Withdrawn this year: %@ — this room comes back on January 1.": "المسحوب هذا العام: %@ — يعود هذا السقف في 1 يناير.",
        "No recent losses to watch.": "لا توجد خسائر حديثة للمراقبة.",
        "Superficial loss watch": "مراقبة الخسارة الصورية",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "إذا بعت بخسارة في حساب غير مسجّل واشتريت أنت (أو زوجك/زوجتك) الورقة المالية نفسها خلال 30 يومًا قبل البيع أو بعده — في أي حساب، بما في ذلك TFSA أو RRSP — وما زلت تحتفظ بها، فإن CRA ترفض احتساب الخسارة. يتحقق Orion من جميع حساباتك المرتبطة. لا تُشمل حسابات الزوج/الزوجة ما لم تكن مرتبطة.",
        "Sold at a loss on %@ in %@": "بيع بخسارة بتاريخ %@ في %@",
        "Don't buy %@ in any account until %@ to keep this loss.": "لا تشترِ %@ في أي حساب حتى %@ للاحتفاظ بهذه الخسارة.",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "يُرجَّح أنها خسارة صورية — فقد اشتريتها مجددًا خلال 30 يومًا وما زلت تحتفظ بها.",
        "Bought on %@ in %@": "شراء بتاريخ %@ في %@",
        "Amount in CAD": "المبلغ بالدولار الكندي",
        "%@ room available on January 1, %d": "سقف %@ المتاح في 1 يناير %d",
        "Clear": "مسح",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "تجده في CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "استخدم حد خصم RRSP الوارد في أحدث Notice of Assessment أو في CRA My Account.",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "تجده في CRA My Account. الحد السنوي لـ FHSA هو $8,000 بالإضافة إلى أي مبلغ مُرحَّل.",
        "AI Research Snapshot": "ملخص بحثي سريع بالذكاء الاصطناعي",
        "Positive": "إيجابي",
        "Mixed": "متباين",
        "Negative": "سلبي",
        "What to Watch": "ما يجدر متابعته",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "ملخص بحثي مُنشأ بالذكاء الاصطناعي لأغراض تعليمية. ليس توصية بالشراء أو البيع.",
        "Get a side-by-side comparison with an AI summary": "احصل على مقارنة جنبًا إلى جنب مع ملخص بالذكاء الاصطناعي",
        "Example Portfolio to Explore": "محفظة نموذجية للاستكشاف",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "مثال تعليمي للتجربة في التداول التجريبي — ليس توصية. قم ببحثك الخاص قبل الاستثمار.",
        "Ideas to Explore": "أفكار للاستكشاف",
        "Popular names in your interests · not a recommendation": "أسماء رائجة ضمن اهتماماتك · ليست توصية",
        "Help Orion tailor what it explains and shows you": "ساعد Orion على تخصيص ما يشرحه ويعرضه لك",
        "Pick the categories you want to follow and learn about": "اختر الفئات التي تريد متابعتها والتعرّف عليها",
        "Update the categories you follow": "حدّث الفئات التي تتابعها",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "ميزات الذكاء الاصطناعي متوقفة. اسمح بالمشاركة مع Google Gemini في المزيد → مشاركة البيانات مع الذكاء الاصطناعي لاستخدامها.",
        "Before you use Orion AI": "قبل استخدام Orion AI",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "تعمل ميزات الذكاء الاصطناعي في Orion بواسطة Google Gemini، وهي خدمة تابعة لجهة خارجية. للإجابة عليك، يرسل Orion إلى Google:",
        "What you type or say to Orion, and any images or files you attach": "ما تكتبه أو تقوله لـ Orion، وأي صور أو ملفات ترفقها",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "بيانات السوق العامة للأسهم التي تسأل عنها (الأسعار، الأساسيات، عناوين الأخبار)",
        "Your language and the investing preferences you chose": "لغتك وتفضيلات الاستثمار التي اخترتها",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "لا يرسل Orion أرصدة حساباتك المرتبطة أو ممتلكاتك أو أرقام حساباتك أو اسمك أو بريدك الإلكتروني إلى الذكاء الاصطناعي.",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AI مخصص للتعليم والبحث. وهو ليس مستشارًا مسجّلًا ولا يخبرك بما تشتريه أو تبيعه.",
        "You can turn this off any time in More → AI Data Sharing.": "يمكنك إيقاف ذلك في أي وقت من المزيد → مشاركة البيانات مع الذكاء الاصطناعي.",
        "Google processes this data under its own terms and may handle it outside Canada.": "تعالج Google هذه البيانات وفق شروطها الخاصة وقد تعالجها خارج كندا.",
        "Allow and continue": "السماح والمتابعة",
        "Not now": "ليس الآن",
        "AI Data Sharing": "مشاركة البيانات مع الذكاء الاصطناعي",
        "Send your AI questions to Google Gemini": "إرسال أسئلتك للذكاء الاصطناعي إلى Google Gemini",
        "Disclaimer": "إخلاء المسؤولية",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "يقدّم Orion Finance المعلومات والتعليم فقط. وهو ليس مستشار استثمار مسجّلًا أو وسيطًا أو مختص ضرائب، ولا يُعد أي شيء في التطبيق توصية بشراء أي ورقة مالية أو بيعها أو الاحتفاظ بها.",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "قد يكون المحتوى المُنشأ بالذكاء الاصطناعي خاطئًا أو قديمًا. قد تكون بيانات السوق متأخرة. تأتي بيانات الحسابات المرتبطة من مؤسساتك عبر SnapTrade وPlaid وقد لا تطابق كشوف حساباتك الرسمية.",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "الميزات الضريبية تقديرات لمساعدتك على رصد المشكلات. تأكّد من سقف مساهمتك في CRA My Account واستشر مختصًا مؤهلًا قبل اتخاذ القرارات.",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "يقرأ Orion حساباتك فقط. لا يمكنه التداول أو تحويل الأموال أو تغيير أي شيء لدى مؤسساتك.",
