        "Question %d of %d": "प्रश्न %d, कुल %d में से",
        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "विकास के लिए आप बड़े उतार-चढ़ाव से सहज हैं। Orion ग्रोथ कंपनियों और नए रुझानों को समझाएगा — उनके जोखिमों सहित।",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "आप विकास और स्थिरता के बीच संतुलन रखते हैं। Orion ग्रोथ कंपनियों और अधिक स्थिर निवेशों, दोनों को समझाएगा, और यह भी कि वे एक साथ कैसे फ़िट होते हैं।",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "आप स्थिरता को प्राथमिकता देते हैं। Orion समझाते समय विविधीकरण, आय देने वाले निवेशों और आपके पास जो है उसकी सुरक्षा पर अधिक ध्यान देगा।",
        "Prices often move more than usual around an earnings report.": "अर्निंग्स रिपोर्ट के आसपास कीमतें अक्सर सामान्य से अधिक बदलती हैं।",
        "Markets are closed for the weekend": "सप्ताहांत के कारण बाज़ार बंद हैं",
        "Markets have closed for the day": "आज के लिए बाज़ार बंद हो चुके हैं",
        "Markets open at 9:30 AM ET": "बाज़ार 9:30 AM ET पर खुलते हैं",
        "Markets are open · close at 4:00 PM ET": "बाज़ार खुले हैं · 4:00 PM ET पर बंद होंगे",
        "As of %@ ET": "%@ ET तक",
        "Add %@ to watchlist": "%@ को वॉचलिस्ट में जोड़ें",
        "%@ added to watchlist": "%@ वॉचलिस्ट में जोड़ा गया",
        "Added": "जोड़ा गया",
        "Dismiss": "खारिज करें",
        "Adding %@…": "%@ जोड़ा जा रहा है…",
        "%@ was added here but couldn't be saved to your account.": "%@ यहाँ जोड़ा गया, लेकिन आपके खाते में सहेजा नहीं जा सका।",
        "Added for this session. Sign in to keep your watchlist.": "इस सत्र के लिए जोड़ा गया। अपनी वॉचलिस्ट सहेजने के लिए साइन इन करें।",
        "Couldn't add %@. Check your connection and try again.": "%@ नहीं जोड़ा जा सका। अपना कनेक्शन जाँचें और फिर से कोशिश करें।",
        "%@ is already in your watchlist.": "%@ पहले से आपकी वॉचलिस्ट में है।",
        "D/E": "D/E",
        "ROE": "ROE",
        "Beta": "Beta",
        "P/B": "P/B",
        "P/E": "P/E",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "ऑपरेटिंग मार्जिन: वेतन, अनुसंधान और मार्केटिंग जैसी सभी परिचालन लागतों के बाद राजस्व का बचा हुआ हिस्सा। यह दिखाता है कि ब्याज और करों से पहले मुख्य व्यवसाय कितना लाभदायक है।",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "उत्पाद या सेवा बनाने की प्रत्यक्ष लागत के बाद राजस्व का बचा हुआ हिस्सा। 70% सकल मार्जिन का अर्थ है कि बिक्री के हर $100 में से $70 बाकी सभी खर्चों के लिए बचते हैं।",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "डेट-टू-इक्विटी: कुल ऋण को शेयरधारकों की इक्विटी से भाग देने पर मिलने वाला अनुपात। अधिक संख्या का अर्थ है कि कंपनी उधार पर अधिक निर्भर है, जिससे लाभ और जोखिम दोनों बढ़ जाते हैं। सामान्य स्तर उद्योग के अनुसार काफ़ी अलग होते हैं।",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "इक्विटी पर रिटर्न: वार्षिक लाभ को शेयरधारकों की इक्विटी से भाग देने पर मिलने वाला अनुपात। यह दिखाता है कि कंपनी निवेश की गई पूंजी को कितनी कुशलता से लाभ में बदलती है। बहुत अधिक ROE भारी उधार के कारण भी हो सकता है।",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "समग्र बाज़ार की तुलना में स्टॉक आम तौर पर कितना ऊपर-नीचे हुआ है। 1 का अर्थ है बाज़ार के साथ चलना, 1 से अधिक का अर्थ है ज़्यादा उतार-चढ़ाव, 1 से कम का अर्थ है कम उतार-चढ़ाव। यह पिछली अस्थिरता बताता है, भविष्य के रिटर्न नहीं।",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "डिविडेंड यील्ड: प्रति शेयर वार्षिक डिविडेंड को शेयर मूल्य से भाग देने पर मिलने वाला अनुपात। 2% यील्ड का अर्थ है हर $100 के निवेश पर सालाना लगभग $2। असामान्य रूप से ऊँची यील्ड का मतलब हो सकता है कि बाज़ार डिविडेंड में कटौती की उम्मीद कर रहा है।",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "एक वर्ष पहले की तुलना में कंपनी की बिक्री कितनी बढ़ी। यह लागत से पहले व्यवसाय की माँग दिखाता है — वृद्धि लाभदायक है या नहीं, यह जानने के लिए इसे मार्जिन के साथ देखें।",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "एक वर्ष पहले की तुलना में प्रति शेयर आय कितनी बढ़ी। लगातार वृद्धि आम तौर पर ऊँचे मूल्यांकन को सहारा देती है; किसी एक वर्ष की मज़बूत वृद्धि एकबारगी मदों के कारण भी हो सकती है।",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "प्राइस-टू-बुक अनुपात: शेयर मूल्य को कंपनी की प्रति शेयर बुक वैल्यू (संपत्ति घटा देनदारियाँ) से भाग देने पर मिलने वाला अनुपात। 1 से कम का अर्थ है कि बाज़ार कंपनी का मूल्य उसकी लेखांकन नेट वर्थ से कम आँक रहा है। यह सॉफ़्टवेयर कंपनियों की तुलना में बैंकों और भारी संपत्ति वाले व्यवसायों के लिए अधिक सार्थक है।",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "प्राइस-टू-अर्निंग्स अनुपात: शेयर मूल्य को पिछले एक वर्ष की कंपनी की प्रति शेयर आय से भाग देने पर मिलने वाला अनुपात। यह दिखाता है कि निवेशक लाभ के हर डॉलर के लिए कितने डॉलर चुकाते हैं। अधिक संख्या का अर्थ अक्सर यह होता है कि निवेशक तेज़ वृद्धि की उम्मीद करते हैं — या कि स्टॉक महँगा है। समान कंपनियों से तुलना करने पर यह सबसे उपयोगी है।",
        "Generate snapshot": "स्नैपशॉट बनाएँ",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "%@ का AI द्वारा लिखा संक्षिप्त शोध सारांश: स्टॉक को क्या प्रभावित कर रहा है, मुख्य जोखिम और किन बातों पर नज़र रखें। यह कोई सिफ़ारिश नहीं है।",
        "Couldn't generate the snapshot right now.": "अभी स्नैपशॉट नहीं बनाया जा सका।",
