        "Connect a Bank": "बैंक कनेक्ट करें",
        "Connect Another Bank": "दूसरा बैंक कनेक्ट करें",
        "Brokerages connect securely through SnapTrade, banks through Plaid. You sign in on your institution's own page.": "ब्रोकरेज SnapTrade के ज़रिए और बैंक Plaid के ज़रिए सुरक्षित रूप से कनेक्ट होते हैं। आप अपनी संस्था के अपने पेज पर साइन इन करते हैं।",
        "Sign in to this bank again to keep it updated.": "इसे अपडेट रखने के लिए इस बैंक में फिर से साइन इन करें।",
