        "%d connections need attention": "%d कनेक्शन पर ध्यान देना ज़रूरी है",
        "Your net worth may be out of date. Tap to fix.": "आपकी नेट वर्थ पुरानी हो सकती है। ठीक करने के लिए टैप करें।",
        "Non-registered": "नॉन-रजिस्टर्ड",
        "Tax Assistant": "टैक्स असिस्टेंट",
        "TFSA · RRSP · FHSA room and superficial loss watch": "TFSA · RRSP · FHSA सीमा और सुपरफ़िशियल लॉस निगरानी",
        "%d items need attention": "%d आइटम पर ध्यान देना ज़रूरी है",
        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "केवल जानकारी के लिए, कर सलाह नहीं। अपने आँकड़े CRA My Account में या किसी कर विशेषज्ञ से जाँचें।",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "TFSA, RRSP और FHSA योगदान ट्रैक करने के लिए ब्रोकरेज लिंक करें।",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "आपके लिंक किए गए खातों में कोई TFSA, RRSP या FHSA खाता नहीं मिला।",
        "%d contribution room": "%d योगदान सीमा",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "योगदान की गणना इस कैलेंडर वर्ष में आपके लिंक किए गए खातों से की जाती है। संस्थाओं के बीच ट्रांसफ़र नहीं गिने जाते। वर्ष के पहले 60 दिनों में किए गए RRSP योगदान पिछले कर वर्ष पर लागू हो सकते हैं।",
        "Set room": "सीमा सेट करें",
        "Edit room": "सीमा बदलें",
        "Contributed this year": "इस वर्ष का योगदान",
        "Room left": "शेष सीमा",
        "Over your room by": "सीमा से अधिक",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "CRA अतिरिक्त योगदान पर हर महीने 1 प्रतिशत जुर्माना लेता है (यहाँ %@)। जुर्माना रोकने के लिए अतिरिक्त राशि निकाल लें।",
        "Within the $2,000 RRSP over-contribution allowance.": "$2,000 की RRSP अतिरिक्त योगदान छूट के भीतर।",
        "Enter your room from CRA My Account to see what's left.": "कितनी सीमा बची है, यह देखने के लिए CRA My Account से अपनी सीमा दर्ज करें।",
        "Withdrawn this year: %@ — this room comes back on January 1.": "इस वर्ष निकाली गई राशि: %@ — यह सीमा 1 जनवरी को वापस मिल जाएगी।",
        "No recent losses to watch.": "निगरानी के लिए कोई हालिया नुकसान नहीं।",
        "Superficial loss watch": "सुपरफ़िशियल लॉस निगरानी",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "अगर आप किसी नॉन-रजिस्टर्ड खाते में घाटे पर बेचते हैं और आप (या आपका जीवनसाथी) उससे 30 दिन पहले या बाद में किसी भी खाते में — TFSA या RRSP सहित — वही सिक्योरिटी खरीदते हैं और उसे अभी भी रखते हैं, तो CRA उस नुकसान को अस्वीकार कर देता है। Orion आपके सभी लिंक किए गए खातों की जाँच करता है। जीवनसाथी के खाते तब तक शामिल नहीं होते जब तक वे लिंक न हों।",
        "Sold at a loss on %@ in %@": "%@ को %@ में घाटे पर बेचा",
        "Don't buy %@ in any account until %@ to keep this loss.": "इस नुकसान को बनाए रखने के लिए %@ को %@ तक किसी भी खाते में न खरीदें।",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "संभवतः सुपरफ़िशियल लॉस — आपने इसे 30 दिनों के भीतर फिर से खरीदा और अभी भी रखे हुए हैं।",
        "Bought on %@ in %@": "%@ को %@ में खरीदा",
        "Amount in CAD": "राशि (CAD)",
        "%@ room available on January 1, %d": "%@ सीमा, 1 जनवरी %d से उपलब्ध",
        "Clear": "साफ़ करें",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "इसे CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room में देखें।",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "अपने नवीनतम Notice of Assessment या CRA My Account में दी गई RRSP कटौती सीमा का उपयोग करें।",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "इसे CRA My Account में देखें। FHSA की वार्षिक सीमा $8,000 है, साथ में कोई भी कैरी-फ़ॉरवर्ड राशि।",
        "AI Research Snapshot": "AI रिसर्च स्नैपशॉट",
        "Positive": "सकारात्मक",
        "Mixed": "मिला-जुला",
        "Negative": "नकारात्मक",
        "What to Watch": "किन बातों पर नज़र रखें",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "सीखने के लिए AI द्वारा तैयार शोध सारांश। यह ख़रीदने या बेचने की सिफ़ारिश नहीं है।",
        "Get a side-by-side comparison with an AI summary": "AI सारांश के साथ आमने-सामने तुलना देखें",
        "Example Portfolio to Explore": "देखने के लिए उदाहरण पोर्टफोलियो",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "पेपर ट्रेडिंग में आज़माने के लिए एक शैक्षिक उदाहरण — कोई सिफ़ारिश नहीं। निवेश से पहले स्वयं शोध करें।",
        "Ideas to Explore": "जानने लायक विचार",
        "Popular names in your interests · not a recommendation": "आपकी रुचियों में लोकप्रिय नाम · कोई सिफ़ारिश नहीं",
        "Help Orion tailor what it explains and shows you": "Orion को यह तय करने में मदद करें कि वह आपको क्या समझाए और दिखाए",
        "Pick the categories you want to follow and learn about": "वे श्रेणियाँ चुनें जिन्हें आप फ़ॉलो करना और समझना चाहते हैं",
        "Update the categories you follow": "अपनी फ़ॉलो की गई श्रेणियाँ अपडेट करें",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "AI सुविधाएँ बंद हैं। इनका उपयोग करने के लिए अधिक → AI डेटा शेयरिंग में Google Gemini के साथ शेयरिंग की अनुमति दें।",
        "Before you use Orion AI": "Orion AI का उपयोग करने से पहले",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "Orion की AI सुविधाएँ एक थर्ड-पार्टी सेवा, Google Gemini, द्वारा संचालित हैं। आपको जवाब देने के लिए Orion, Google को यह भेजता है:",
        "What you type or say to Orion, and any images or files you attach": "आप Orion को जो लिखते या बोलते हैं, और आपके द्वारा संलग्न कोई भी चित्र या फ़ाइलें",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "जिन स्टॉक के बारे में आप पूछते हैं उनका सार्वजनिक बाज़ार डेटा (कीमतें, फ़ंडामेंटल्स, समाचार शीर्षक)",
        "Your language and the investing preferences you chose": "आपकी भाषा और आपके द्वारा चुनी गई निवेश प्राथमिकताएँ",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "Orion आपके लिंक किए गए खातों का बैलेंस, होल्डिंग्स, खाता संख्याएँ, नाम या ईमेल AI को नहीं भेजता।",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AI शिक्षा और शोध के लिए है। यह कोई पंजीकृत सलाहकार नहीं है और आपको यह नहीं बताता कि क्या ख़रीदें या बेचें।",
        "You can turn this off any time in More → AI Data Sharing.": "आप इसे कभी भी अधिक → AI डेटा शेयरिंग में बंद कर सकते हैं।",
        "Google processes this data under its own terms and may handle it outside Canada.": "Google इस डेटा को अपनी शर्तों के तहत प्रोसेस करता है और इसे कनाडा के बाहर भी संभाल सकता है।",
        "Allow and continue": "अनुमति दें और जारी रखें",
        "Not now": "अभी नहीं",
        "AI Data Sharing": "AI डेटा शेयरिंग",
        "Send your AI questions to Google Gemini": "अपने AI प्रश्न Google Gemini को भेजें",
        "Disclaimer": "अस्वीकरण",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "Orion Finance केवल जानकारी और शिक्षा प्रदान करता है। यह कोई पंजीकृत निवेश सलाहकार, डीलर या कर विशेषज्ञ नहीं है, और ऐप में कुछ भी किसी सिक्योरिटी को ख़रीदने, बेचने या रखने की सिफ़ारिश नहीं है।",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "AI द्वारा तैयार सामग्री गलत या पुरानी हो सकती है। बाज़ार डेटा में देरी हो सकती है। लिंक किए गए खातों का डेटा आपकी संस्थाओं से SnapTrade और Plaid के ज़रिए आता है और हो सकता है कि यह आपके आधिकारिक स्टेटमेंट से मेल न खाए।",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "कर सुविधाएँ अनुमान हैं, जो आपको समस्याएँ पहचानने में मदद करती हैं। निर्णय लेने से पहले CRA My Account में अपनी योगदान सीमा की पुष्टि करें और किसी योग्य विशेषज्ञ से बात करें।",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "Orion केवल आपके खाते पढ़ता है। यह ट्रेड नहीं कर सकता, पैसे ट्रांसफ़र नहीं कर सकता और आपकी संस्थाओं में कुछ भी नहीं बदल सकता।",
