        "Disconnect": "डिस्कनेक्ट करें",
        "%@ holdings will be removed from Orion. Your brokerage account itself is not affected.": "%@ की होल्डिंग्स Orion से हटा दी जाएँगी। आपके ब्रोकरेज खाते पर इसका कोई असर नहीं पड़ेगा।",
        "See your real holdings": "अपनी वास्तविक होल्डिंग्स देखें",
        "Link Wealthsimple, other brokerages or your bank to see your net worth in Orion. Read-only: Orion can never trade or move money, and never sees your passwords.": "अपनी नेट वर्थ Orion में देखने के लिए Wealthsimple, अन्य ब्रोकरेज या अपना बैंक लिंक करें। केवल पढ़ने के लिए: Orion कभी ट्रेड या पैसे ट्रांसफ़र नहीं कर सकता, और आपके पासवर्ड कभी नहीं देखता।",
