        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "Заради зростання ви готові до більших коливань. Orion пояснюватиме компанії зростання та нові тенденції — разом із їхніми ризиками.",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "Ви шукаєте баланс між зростанням і стабільністю. Orion пояснюватиме як компанії зростання, так і стабільніші інвестиції, а також те, як вони поєднуються.",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "Для вас на першому місці стабільність. У поясненнях Orion більше уваги приділятиме диверсифікації, дохідним інвестиціям і збереженню того, що у вас уже є.",
        "Prices often move more than usual around an earnings report.": "Навколо публікації фінансового звіту ціни часто коливаються сильніше, ніж зазвичай.",
