        "%@ was added here but couldn't be saved to your account.": "%@ додано тут, але не вдалося зберегти у вашому обліковому записі.",
        "Added for this session. Sign in to keep your watchlist.": "Додано на цей сеанс. Увійдіть, щоб зберегти список спостереження.",
        "Couldn't add %@. Check your connection and try again.": "Не вдалося додати %@. Перевірте з’єднання та спробуйте ще раз.",
