        "P/E": "P/E",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "Операційна маржа: частка виручки, що залишається після всіх операційних витрат, як-от зарплати, дослідження та маркетинг. Вона показує, наскільки прибутковий основний бізнес до сплати відсотків і податків.",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "Частка виручки, що залишається після прямих витрат на виробництво продукту чи послуги. Валова маржа 70% означає, що з кожних $100 продажів $70 залишаються на всі інші витрати.",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "Борг до капіталу: загальний борг, поділений на власний капітал акціонерів. Вище значення означає, що компанія більше покладається на позики, а це посилює і прибутки, і ризики. Нормальний рівень суттєво різниться залежно від галузі.",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "Рентабельність капіталу: річний прибуток, поділений на власний капітал акціонерів. Показує, наскільки ефективно компанія перетворює вкладений капітал на прибуток. Дуже високий ROE може бути й наслідком великих позик.",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "Наскільки сильно акція зазвичай рухалася відносно ринку загалом. 1 — рухається разом із ринком, понад 1 — коливається сильніше, менше 1 — слабше. Показник описує минулу волатильність, а не майбутню дохідність.",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "Дивідендна дохідність: річні дивіденди на акцію, поділені на ціну акції. Дохідність 2% — це приблизно $2 на рік на кожні вкладені $100. Незвично висока дохідність може означати, що ринок очікує скорочення дивідендів.",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "Наскільки зросли продажі компанії порівняно з минулим роком. Показує попит на бізнес без урахування витрат — зіставте його з маржею, щоб зрозуміти, чи зростання прибуткове.",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "Наскільки зріс прибуток на акцію порівняно з минулим роком. Стале зростання зазвичай підтримує вищу оцінку; один вдалий рік може бути наслідком разових чинників.",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "Ціна до балансової вартості: ціна акції, поділена на балансову вартість компанії (активи мінус зобов’язання) на акцію. Значення нижче 1 означає, що ринок оцінює компанію нижче її облікової чистої вартості. Показник важливіший для банків і капіталомістких компаній, ніж для розробників програмного забезпечення.",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "Ціна до прибутку: ціна акції, поділена на прибуток компанії на акцію за останній рік. Показує, скільки доларів інвестори платять за кожен долар прибутку. Вище значення часто означає, що інвестори очікують швидшого зростання — або що акція дорога. Найкорисніший у порівнянні з подібними компаніями.",
        "Generate snapshot": "Створити огляд",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "Короткий аналітичний огляд %@, написаний ШІ: що впливає на акцію, ключові ризики та на що звернути увагу. Не є рекомендацією.",
        "Couldn't generate the snapshot right now.": "Наразі не вдалося створити огляд.",
