        "No recent losses to watch.": "Останнім часом немає збитків, за якими варто стежити.",
        "Superficial loss watch": "Контроль фіктивних збитків",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "Якщо ви продаєте зі збитком на незареєстрованому рахунку, а ви (або ваш чоловік чи дружина) купуєте той самий цінний папір протягом 30 днів до або після продажу — на будь-якому рахунку, зокрема TFSA чи RRSP, — і досі ним володієте, CRA не визнає цей збиток. Orion перевіряє всі ваші підключені рахунки. Рахунки чоловіка чи дружини не враховуються, якщо їх не підключено.",
