        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "Використайте ліміт відрахувань RRSP з останнього Notice of Assessment або з CRA My Account.",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "Його можна знайти в CRA My Account. Річний ліміт FHSA становить $8,000 плюс перенесений залишок.",
