        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "Функції ШІ вимкнено. Щоб ними користуватися, дозвольте передавання даних Google Gemini в розділі Більше → Передавання даних ШІ.",
        "Before you use Orion AI": "Перш ніж користуватися Orion AI",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "Функції ШІ в Orion працюють на основі Google Gemini — стороннього сервісу. Щоб відповісти вам, Orion надсилає Google:",
        "What you type or say to Orion, and any images or files you attach": "Те, що ви пишете чи кажете Orion, а також прикріплені зображення чи файли",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "Публічні ринкові дані про акції, якими ви цікавитеся (ціни, фундаментальні показники, заголовки новин)",
        "Your language and the investing preferences you chose": "Вашу мову та обрані вами інвестиційні вподобання",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "Orion не надсилає ШІ баланси підключених рахунків, ваші позиції, номери рахунків, ім’я чи електронну пошту.",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AI призначений для навчання й досліджень. Це не зареєстрований радник, і він не підказує, що купувати чи продавати.",
        "You can turn this off any time in More → AI Data Sharing.": "Це можна будь-коли вимкнути в розділі Більше → Передавання даних ШІ.",
        "Google processes this data under its own terms and may handle it outside Canada.": "Google обробляє ці дані згідно з власними умовами й може робити це за межами Канади.",
        "Allow and continue": "Дозволити й продовжити",
        "Not now": "Не зараз",
        "AI Data Sharing": "Передавання даних ШІ",
        "Send your AI questions to Google Gemini": "Надсилати ваші запитання до ШІ в Google Gemini",
        "Disclaimer": "Застереження",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "Orion Finance надає лише інформацію та навчальні матеріали. Він не є зареєстрованим інвестиційним радником, дилером чи податковим фахівцем, і ніщо в застосунку не є рекомендацією купувати, продавати чи тримати будь-який цінний папір.",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "Вміст, створений ШІ, може бути помилковим або застарілим. Ринкові дані можуть надходити із затримкою. Дані підключених рахунків надходять від ваших установ через SnapTrade і Plaid і можуть не збігатися з офіційними виписками.",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "Податкові функції дають орієнтовні оцінки, щоб допомогти помітити проблеми. Перш ніж ухвалювати рішення, перевірте свій ліміт внесків у CRA My Account і порадьтеся з кваліфікованим фахівцем.",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "Orion лише переглядає ваші рахунки. Він не може торгувати, переказувати кошти чи щось змінювати у ваших установах.",
