        "Investment style: %@": "סגנון השקעה: %@",
        "Question %d of %d": "שאלה %d מתוך %d",
        "You're comfortable with bigger swings in pursuit of growth. Orion will explain growth companies and newer trends — including their risks.": "תנודות גדולות יותר לא מרתיעות אותך כשהמטרה היא צמיחה. Orion יסביר על חברות צמיחה ומגמות חדשות — כולל הסיכונים שלהן.",
        "You balance growth with stability. Orion will explain both growth companies and steadier investments, and how they fit together.": "הגישה שלך משלבת צמיחה ויציבות. Orion יסביר גם על חברות צמיחה וגם על השקעות יציבות יותר, ואיך הן משתלבות זו בזו.",
        "You put stability first. When Orion explains things, it will spend more time on diversification, income investments and protecting what you have.": "אצלך היציבות קודמת לכול. בהסברים שלו, Orion יקדיש יותר זמן לפיזור, להשקעות מניבות ולשמירה על מה שכבר יש לך.",
        "Prices often move more than usual around an earnings report.": "מחירים נוטים לזוז יותר מהרגיל סביב פרסום דוחות כספיים.",
        "Markets are closed for the weekend": "השווקים סגורים בסוף השבוע",
        "Markets have closed for the day": "המסחר להיום הסתיים",
        "Markets open at 9:30 AM ET": "השווקים נפתחים ב-9:30 לפי שעון ET",
        "Markets are open · close at 4:00 PM ET": "השווקים פתוחים · נסגרים ב-16:00 לפי שעון ET",
        "As of %@ ET": "נכון ל-%@ לפי שעון ET",
        "Add %@ to watchlist": "הוספת %@ לרשימת המעקב",
        "%@ added to watchlist": "%@ נוסף לרשימת המעקב",
        "Added": "נוסף",
        "Dismiss": "סגירה",
        "Adding %@…": "%@ מתווסף…",
        "%@ was added here but couldn't be saved to your account.": "%@ נוסף כאן, אך לא ניתן היה לשמור אותו בחשבון שלך.",
        "Added for this session. Sign in to keep your watchlist.": "נוסף לסשן הנוכחי בלבד. יש להתחבר כדי לשמור את רשימת המעקב.",
        "Couldn't add %@. Check your connection and try again.": "לא ניתן היה להוסיף את %@. יש לבדוק את החיבור ולנסות שוב.",
        "%@ is already in your watchlist.": "%@ כבר נמצא ברשימת המעקב שלך.",
        "D/E": "חוב/הון",
        "ROE": "ROE",
        "Beta": "בטא",
        "P/B": "מכפיל הון",
        "P/E": "מכפיל רווח",
        "Operating margin: the share of revenue left after all operating costs such as salaries, research and marketing. It shows how profitable the core business is before interest and taxes.": "שיעור רווח תפעולי: החלק מההכנסות שנותר אחרי כל העלויות התפעוליות, כמו שכר, מחקר ושיווק. הוא מראה עד כמה העסק המרכזי רווחי לפני ריבית ומסים.",
        "The share of revenue left after the direct cost of making the product or service. A 70% gross margin keeps $70 of every $100 in sales to pay for everything else.": "החלק מההכנסות שנותר אחרי העלות הישירה של ייצור המוצר או השירות. שיעור רווח גולמי של 70% משאיר $70 מכל $100 של מכירות לכיסוי כל שאר ההוצאות.",
        "Debt-to-equity: total debt divided by shareholders' equity. A higher number means the company relies more on borrowing, which magnifies both gains and risks. Normal levels vary widely by industry.": "יחס חוב להון: סך החוב חלקי ההון העצמי של בעלי המניות. מספר גבוה יותר פירושו שהחברה נשענת יותר על הלוואות, מה שמגדיל גם את הרווחים וגם את הסיכונים. הרמות המקובלות משתנות מאוד בין ענפים.",
        "Return on equity: yearly profit divided by shareholders' equity. It shows how efficiently the company turns invested capital into profit. Very high ROE can also come from heavy borrowing.": "תשואה על ההון: הרווח השנתי חלקי ההון העצמי של בעלי המניות. המדד מראה באיזו יעילות החברה הופכת הון מושקע לרווח. ROE גבוה מאוד יכול לנבוע גם ממינוף כבד.",
        "How much the stock has tended to move relative to the overall market. 1 moves with the market, above 1 swings more, below 1 swings less. It describes past volatility, not future returns.": "עד כמה המניה נטתה לזוז ביחס לשוק כולו. 1 פירושו תנועה יחד עם השוק, מעל 1 תנודות גדולות יותר, מתחת ל-1 תנודות קטנות יותר. המדד מתאר תנודתיות בעבר, לא תשואות עתידיות.",
        "Dividend yield: yearly dividends per share divided by the share price. A 2% yield pays about $2 a year for every $100 invested. An unusually high yield can mean the market expects the dividend to be cut.": "תשואת דיבידנד: הדיבידנדים השנתיים למניה חלקי מחיר המניה. תשואה של 2% משלמת כ-$2 בשנה על כל $100 שהושקעו. תשואה גבוהה באופן חריג עשויה להעיד שהשוק צופה קיצוץ בדיבידנד.",
        "How much the company's sales grew compared with a year earlier. It shows demand for the business before costs — pair it with margins to see whether the growth is profitable.": "בכמה גדלו מכירות החברה לעומת השנה הקודמת. הנתון משקף את הביקוש לעסק לפני עלויות — כדאי לבחון אותו יחד עם שיעורי הרווח כדי לראות אם הצמיחה רווחית.",
        "How much earnings per share grew compared with a year earlier. Sustained growth tends to support a higher valuation; a single strong year can come from one-off items.": "בכמה גדל הרווח למניה לעומת השנה הקודמת. צמיחה מתמשכת נוטה לתמוך בשווי גבוה יותר; שנה חזקה בודדת עשויה לנבוע מפריטים חד-פעמיים.",
        "Price-to-book ratio: the share price divided by the company's book value (assets minus liabilities) per share. Below 1 means the market values the company at less than its accounting net worth. It's more meaningful for banks and asset-heavy businesses than for software companies.": "מכפיל הון: מחיר המניה חלקי הערך בספרים (נכסים פחות התחייבויות) למניה. ערך מתחת ל-1 פירושו שהשוק מעריך את החברה בפחות מהשווי הנקי החשבונאי שלה. המדד משמעותי יותר לבנקים ולעסקים עתירי נכסים מאשר לחברות תוכנה.",
        "Price-to-earnings ratio: the share price divided by the company's earnings per share over the last year. It shows how many dollars investors pay for each dollar of profit. A higher number often means investors expect faster growth — or that the stock is expensive. It's most useful compared with similar companies.": "מכפיל רווח: מחיר המניה חלקי הרווח למניה של החברה בשנה האחרונה. הוא מראה כמה דולרים משלמים המשקיעים על כל דולר של רווח. מספר גבוה יותר פירושו לעיתים קרובות שהמשקיעים מצפים לצמיחה מהירה יותר — או שהמניה יקרה. הוא שימושי במיוחד בהשוואה לחברות דומות.",
        "Generate snapshot": "יצירת תקציר",
        "A short, AI-written research summary of %@: what's driving the stock, key risks and what to watch. Not a recommendation.": "תקציר מחקר קצר על %@ שנכתב על ידי AI: מה מניע את המניה, סיכונים עיקריים ומה כדאי לעקוב אחריו. לא המלצה.",
        "Couldn't generate the snapshot right now.": "לא ניתן ליצור את התקציר כרגע.",
        "Explain %@ for %@ with Orion AI": "הסבר על %@ של %@ עם Orion AI",
        "Retry": "ניסיון חוזר",
        "Couldn't load an explanation right now.": "לא ניתן לטעון הסבר כרגע.",
        "Asking Orion…": "השאלה נשלחת ל-Orion…",
        "For %@": "עבור %@",
        "Linked Accounts": "חשבונות מקושרים",
        "Bank": "בנק",
        "Disconnect this bank?": "לנתק את הבנק הזה?",
        "%@ accounts will be removed from Orion. Your bank account itself is not affected.": "החשבונות של %@ יוסרו מ-Orion. חשבון הבנק עצמו לא יושפע.",
        "Connect a Bank": "חיבור בנק",
        "Connect Another Bank": "חיבור בנק נוסף",
        "Brokerages connect securely through SnapTrade, banks through Plaid. You sign in on your institution's own page.": "ברוקרים מתחברים בצורה מאובטחת דרך SnapTrade, ובנקים דרך Plaid. ההתחברות נעשית בדף של המוסד עצמו.",
        "Sign in to this bank again to keep it updated.": "יש להתחבר שוב לבנק הזה כדי שהנתונים ימשיכו להתעדכן.",
        "Couldn't load this bank right now.": "לא ניתן לטעון את הבנק הזה כרגע.",
        "Past 5 days": "5 הימים האחרונים",
        "Past month": "החודש האחרון",
