        "Total": "סה״כ",
        "By institution": "לפי מוסד",
        "Show total": "הצגת הסכום הכולל",
        "Split by institution": "פילוח לפי מוסד",
        "%@ needs you to sign in again": "נדרשת התחברות מחדש ל-%@",
        "%@ hasn't updated since %@": "%@ לא התעדכן מאז %@",
        "%@ hasn't updated recently": "%@ לא התעדכן לאחרונה",
        "%@ couldn't be loaded": "לא ניתן היה לטעון את %@",
        "Account connection": "חיבור חשבון",
        "%d connections need attention": "%d חיבורים דורשים טיפול",
        "Your net worth may be out of date. Tap to fix.": "ייתכן שהשווי הנקי שלך אינו עדכני. יש להקיש לתיקון.",
        "Non-registered": "חשבון לא רשום",
        "Tax Assistant": "עוזר מס",
        "TFSA · RRSP · FHSA room and superficial loss watch": "מכסות TFSA · RRSP · FHSA ומעקב הפסד שטחי",
        "%d items need attention": "%d פריטים דורשים תשומת לב",
        "Information only, not tax advice. Check your figures in CRA My Account or with a tax professional.": "למידע בלבד, לא ייעוץ מס. מומלץ לבדוק את הנתונים ב-CRA My Account או מול גורם מקצועי בתחום המס.",
        "Link a brokerage to track TFSA, RRSP and FHSA contributions.": "יש לקשר ברוקר כדי לעקוב אחר ההפקדות ל-TFSA, ל-RRSP ול-FHSA.",
        "No TFSA, RRSP or FHSA accounts found among your linked accounts.": "לא נמצאו חשבונות TFSA, RRSP או FHSA בין החשבונות המקושרים שלך.",
        "%d contribution room": "מכסת הפקדה ל-%d",
        "Contributions are counted from your linked accounts this calendar year. Transfers between institutions aren't counted. RRSP contributions in the first 60 days of the year can apply to the previous tax year.": "ההפקדות נספרות מהחשבונות המקושרים שלך בשנה הקלנדרית הנוכחית. העברות בין מוסדות אינן נספרות. הפקדות ל-RRSP ב-60 הימים הראשונים של השנה יכולות להיזקף לשנת המס הקודמת.",
        "Set room": "הגדרת מכסה",
        "Edit room": "עריכת מכסה",
        "Contributed this year": "הופקד השנה",
        "Room left": "יתרת מכסה",
        "Over your room by": "חריגה מהמכסה בסך",
        "CRA charges 1%% per month on over-contributions (%@ here). Withdraw the excess to stop the penalty.": "CRA גובה קנס של 1%% לחודש על הפקדות עודפות (כאן: %@). משיכת העודף תעצור את הקנס.",
        "Within the $2,000 RRSP over-contribution allowance.": "בתוך מרווח ההפקדה העודפת של $2,000 המותר ב-RRSP.",
        "Enter your room from CRA My Account to see what's left.": "יש להזין את המכסה מ-CRA My Account כדי לראות כמה נותר.",
        "Withdrawn this year: %@ — this room comes back on January 1.": "נמשך השנה: %@ — מכסה זו תחזור ב-1 בינואר.",
        "No recent losses to watch.": "אין הפסדים אחרונים למעקב.",
        "Superficial loss watch": "מעקב הפסד שטחי",
        "If you sell at a loss in a non-registered account and you (or your spouse) buy the same security within 30 days before or after — in any account, including a TFSA or RRSP — and still hold it, CRA denies the loss. Orion checks all your linked accounts. Spouses' accounts aren't included unless linked.": "במכירה בהפסד בחשבון לא רשום, אם אותו נייר ערך נקנה שוב על ידך (או על ידי בן או בת הזוג) תוך 30 יום לפני המכירה או אחריה — בכל חשבון, כולל TFSA או RRSP — ועדיין מוחזק, CRA לא תכיר בהפסד. Orion בודק את כל החשבונות המקושרים שלך. חשבונות של בני זוג אינם נכללים אלא אם קושרו.",
        "Sold at a loss on %@ in %@": "נמכר בהפסד בתאריך %@ ב-%@",
        "Don't buy %@ in any account until %@ to keep this loss.": "כדי לשמור על ההפסד, אין לקנות %@ בשום חשבון עד %@.",
        "Likely a superficial loss — you bought it again within 30 days and still hold it.": "ככל הנראה הפסד שטחי — הנייר נקנה שוב תוך 30 יום ועדיין מוחזק.",
        "Bought on %@ in %@": "נקנה בתאריך %@ ב-%@",
        "Amount in CAD": "סכום ב-CAD",
        "%@ room available on January 1, %d": "מכסת %@ זמינה ב-1 בינואר %d",
        "Clear": "ניקוי",
        "Find it in CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.": "אפשר למצוא זאת ב-CRA My Account → RRSP, TFSA and FHSA → TFSA contribution room.",
        "Use the RRSP deduction limit on your latest Notice of Assessment or in CRA My Account.": "יש להשתמש במגבלת הניכוי ל-RRSP שמופיעה בהודעת השומה האחרונה (Notice of Assessment) או ב-CRA My Account.",
        "Find it in CRA My Account. The annual FHSA limit is $8,000 plus any carry-forward.": "אפשר למצוא זאת ב-CRA My Account. המגבלה השנתית ל-FHSA היא $8,000, בתוספת יתרה שהועברה משנים קודמות.",
        "AI Research Snapshot": "תקציר מחקר AI",
