        "What to Watch": "על מה לשים לב",
        "AI-generated research summary for education. Not a recommendation to buy or sell.": "תקציר מחקר שנוצר על ידי AI למטרות לימוד. אינו המלצה לקנות או למכור.",
        "Get a side-by-side comparison with an AI summary": "השוואה זה לצד זה עם תקציר AI",
        "Example Portfolio to Explore": "תיק השקעות לדוגמה לעיון",
        "An educational example to try in Paper Trading — not a recommendation. Do your own research before investing.": "דוגמה לימודית לניסיון במסחר המדומה — לא המלצה. מומלץ לבצע מחקר עצמאי לפני השקעה.",
        "Ideas to Explore": "רעיונות לעיון",
        "Popular names in your interests · not a recommendation": "שמות פופולריים בתחומי העניין שלך · לא המלצה",
        "Help Orion tailor what it explains and shows you": "עזרה ל-Orion להתאים את מה שהוא מסביר ומציג לך",
        "Pick the categories you want to follow and learn about": "בחירת הקטגוריות שברצונך לעקוב אחריהן וללמוד עליהן",
        "Update the categories you follow": "עדכון הקטגוריות שבמעקב שלך",
        "AI features are off. Allow sharing with Google Gemini in More → AI Data Sharing to use them.": "תכונות ה-AI כבויות. כדי להשתמש בהן, יש לאשר שיתוף עם Google Gemini בעוד → שיתוף נתונים עם AI.",
        "Before you use Orion AI": "לפני השימוש ב-Orion AI",
        "Orion's AI features are powered by Google Gemini, a third-party service. To answer you, Orion sends Google:": "תכונות ה-AI של Orion מבוססות על Google Gemini, שירות של צד שלישי. כדי לענות לך, Orion שולח ל-Google:",
        "What you type or say to Orion, and any images or files you attach": "מה שמוקלד או נאמר ל-Orion, וכל תמונה או קובץ שמצורפים",
        "Public market data for the stocks you ask about (prices, fundamentals, news headlines)": "נתוני שוק ציבוריים על המניות שעליהן שאלת (מחירים, נתונים פונדמנטליים, כותרות חדשות)",
        "Your language and the investing preferences you chose": "השפה שלך והעדפות ההשקעה שבחרת",
        "Orion does not send your linked account balances, holdings, account numbers, name or email to the AI.": "Orion לא שולח ל-AI את יתרות החשבונות המקושרים שלך, את האחזקות, את מספרי החשבונות, את שמך או את כתובת האימייל שלך.",
        "Orion AI is for education and research. It is not a registered adviser and does not tell you what to buy or sell.": "Orion AI נועד ללמידה ולמחקר. הוא אינו יועץ רשום ואינו אומר לך מה לקנות או למכור.",
        "You can turn this off any time in More → AI Data Sharing.": "אפשר לכבות זאת בכל עת בעוד → שיתוף נתונים עם AI.",
        "Google processes this data under its own terms and may handle it outside Canada.": "Google מעבדת את הנתונים לפי התנאים שלה ועשויה לעבד אותם מחוץ לקנדה.",
        "Allow and continue": "אישור והמשך",
        "Not now": "לא עכשיו",
        "AI Data Sharing": "שיתוף נתונים עם AI",
        "Send your AI questions to Google Gemini": "שליחת שאלות ה-AI שלך ל-Google Gemini",
        "Disclaimer": "כתב ויתור",
        "Orion Finance provides information and education only. It is not a registered investment adviser, dealer or tax professional, and nothing in the app is a recommendation to buy, sell or hold any security.": "Orion Finance מספקת מידע ותוכן לימודי בלבד. האפליקציה אינה יועץ השקעות רשום, סוחר ניירות ערך או גורם מקצועי בתחום המס, ושום דבר בה אינו מהווה המלצה לקנות, למכור או להחזיק נייר ערך כלשהו.",
        "AI-generated content can be wrong or out of date. Market data may be delayed. Linked account data comes from your institutions through SnapTrade and Plaid and may not match your official statements.": "תוכן שנוצר על ידי AI עלול להיות שגוי או לא עדכני. נתוני השוק עשויים להיות מעוכבים. נתוני החשבונות המקושרים מגיעים מהמוסדות שלך דרך SnapTrade ו-Plaid, וייתכן שלא יתאימו לדוחות הרשמיים שלך.",
        "Tax features are estimates to help you spot issues. Confirm your contribution room in CRA My Account and talk to a qualified professional before making decisions.": "תכונות המס הן הערכות שנועדו לעזור באיתור בעיות. יש לאמת את מכסת ההפקדה ב-CRA My Account ולהתייעץ עם גורם מקצועי מוסמך לפני קבלת החלטות.",
        "Orion only reads your accounts. It cannot trade, move money or change anything at your institutions.": "Orion רק קורא את החשבונות שלך. הוא לא יכול לסחור, להעביר כסף או לשנות דבר במוסדות שלך.",
